import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import { Game } from './game/engine';
import { loadRecords } from './game/config';
import type { DiffId, HudData, MsgKind, Summary } from './game/config';
import Hud from './components/Hud';
import type { Msg } from './components/Hud';
import Menu from './components/Menu';
import { GameOverScreen, PauseScreen } from './components/Screens';
import TouchControls from './components/TouchControls';

type Screen = 'menu' | 'play' | 'paused' | 'over';
const PREFS_KEY = 'planeador-prefs';

function loadPrefs(): { diff: DiffId; invert: boolean; muted: boolean } {
  try { const p = JSON.parse(localStorage.getItem(PREFS_KEY) || '{}'); return { diff: p.diff || 'normal', invert: !!p.invert, muted: !!p.muted }; }
  catch { return { diff: 'normal', invert: false, muted: false }; }
}

export default function App() {
  const wrapRef = useRef<HTMLDivElement>(null), gameRef = useRef<Game | null>(null), timers = useRef<number[]>([]), msgId = useRef(0);
  const [prefs] = useState(loadPrefs);
  const [screen, setScreen] = useState<Screen>('menu');
  const [hud, setHud] = useState<HudData | null>(null);
  const [msgs, setMsgs] = useState<Msg[]>([]);
  const [summary, setSummary] = useState<Summary | null>(null);
  const [diff, setDiff] = useState<DiffId>(prefs.diff);
  const [invert, setInvert] = useState(prefs.invert), [muted, setMuted] = useState(prefs.muted);
  const [records, setRecords] = useState(loadRecords);
  const [touch] = useState(() => typeof window !== 'undefined' && ('ontouchstart' in window || navigator.maxTouchPoints > 0));

  const pushMsg = useCallback((text: string, kind: MsgKind) => {
    const id = ++msgId.current;
    setMsgs(m => [...m.slice(-3), { id, text, kind }]);
    timers.current.push(window.setTimeout(() => setMsgs(m => m.filter(x => x.id !== id)), 2600));
  }, []);

  const togglePause = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    if (g.mode === 'play') { g.pause(); setScreen('paused'); } else if (g.mode === 'paused') { g.resume(); setScreen('play'); }
  }, []);

  useEffect(() => {
    if (!wrapRef.current) return;
    const g = new Game(wrapRef.current, {
      onHud: setHud,
      onMessage: pushMsg,
      onGameOver: s => {
        setSummary(s); setScreen('over'); setRecords(loadRecords());
        if (s.newRecord) confetti({ particleCount: 150, spread: 85, origin: { y: 0.35 }, colors: ['#ffc04a', '#ff8a5c', '#ff5e7e', '#fff3d6'] });
      },
    });
    g.input.onPause = togglePause; g.input.onAnyKey = () => g.sfx.unlock(); gameRef.current = g;
    return () => { timers.current.forEach(t => clearTimeout(t)); timers.current = []; g.dispose(); gameRef.current = null; };
  }, [pushMsg, togglePause]);

  useEffect(() => { if (gameRef.current) gameRef.current.input.invert = invert; }, [invert]);
  useEffect(() => { gameRef.current?.setMuted(muted); }, [muted]);
  useEffect(() => { try { localStorage.setItem(PREFS_KEY, JSON.stringify({ diff, invert, muted })); } catch { /* sin almacenamiento */ } }, [diff, invert, muted]);

  const play = () => {
    const g = gameRef.current; if (!g) return;
    setMsgs([]); setHud(null); setSummary(null);
    g.input.invert = invert; g.setMuted(muted); g.start(diff);
    setScreen('play');
  };
  const toMenu = () => { gameRef.current?.toMenu(); setHud(null); setMsgs([]); setScreen('menu'); setRecords(loadRecords()); };
  const game = gameRef.current;

  return (
    <div className="relative w-full h-screen overflow-hidden bg-[#d9906a] select-none" style={{ minHeight: 320 }}>
      <div ref={wrapRef} className="absolute inset-0" onPointerDown={() => game?.sfx.unlock()} />
      <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(ellipse_at_center,transparent_55%,rgba(40,16,30,0.45)_100%)]" />
      {(screen === 'play' || screen === 'paused') && <Hud hud={hud} msgs={msgs} muted={muted} onMute={() => setMuted(m => !m)} onPause={togglePause} />}
      {screen === 'play' && touch && game && <TouchControls input={game.input} onBoost={() => game.input.onBoost?.()} />}
      {screen === 'menu' && (
        <Menu diff={diff} setDiff={setDiff} invert={invert} setInvert={setInvert} records={records} muted={muted} onMute={() => setMuted(m => !m)} onPlay={play} />
      )}
      {screen === 'paused' && <PauseScreen onResume={togglePause} onRestart={play} onMenu={toMenu} />}
      {screen === 'over' && summary && <GameOverScreen s={summary} onRetry={play} onMenu={toMenu} />}
    </div>
  );
}

import { Heart, Magnet, Navigation2, Pause, Shield, Star, Volume2, VolumeX, Wind } from 'lucide-react';
import clsx from 'clsx';
import type { ReactNode } from 'react';
import { POWER_INFO, fmtDist } from '../game/config';
import type { HudData, MsgKind, PowerKind } from '../game/config';
import { SERIF } from './Menu';

export interface Msg { id: number; text: string; kind: MsgKind }
interface Props { hud: HudData | null; msgs: Msg[]; muted: boolean; onMute: () => void; onPause: () => void }

const POWER_ICON: Record<PowerKind, typeof Wind> = { viento: Wind, escudo: Shield, iman: Magnet, reparar: Heart };
const card = 'rounded-xl bg-[#1c1030]/55 ring-1 ring-white/15 backdrop-blur-sm shadow-lg';

const Gauge = ({ label, children }: { label: string; children: ReactNode }) => (
  <div className={clsx(card, 'px-2.5 py-1.5')}><div className="text-[9px] tracking-widest text-white/60">{label}</div>{children}</div>
);

/** Variómetro vertical: aguja de -5 a +5 m/s. */
function Vario({ v, lift }: { v: number; lift: boolean }) {
  const pct = 50 - Math.max(-5, Math.min(5, v)) * 10;
  return (
    <div className={clsx(card, 'w-14 p-1.5 flex flex-col items-center')}>
      <div className="text-[8px] tracking-wider text-white/60 whitespace-nowrap">VARIO m/s</div>
      <div className="relative mt-1 h-36 w-3 rounded-full bg-gradient-to-b from-amber-300 via-white/20 to-sky-500">
        <div className="absolute left-1/2 top-1/2 h-px w-5 -translate-x-1/2 bg-white/70" />
        <div className="absolute -left-2 h-1.5 w-7 rounded-full bg-white shadow-[0_0_10px_white]" style={{ top: `calc(${pct}% - 3px)` }} />
      </div>
      <div className={clsx('mt-1 font-mono text-sm font-bold', v > 0.3 ? 'text-amber-300' : v < -1.5 ? 'text-sky-300' : 'text-white')}>{v > 0 ? '+' : ''}{v.toFixed(1)}</div>
      {lift && <div className="mt-1 text-[9px] font-bold text-amber-300 animate-pulse">TÉRMICA</div>}
    </div>
  );
}

export default function Hud({ hud, msgs, muted, onMute, onPause }: Props) {
  return (
    <div className="pointer-events-none absolute inset-0 text-white">
      {hud && (<>
        <div className="absolute left-3 top-3 flex flex-col gap-2">
          <div className={clsx(card, 'px-3 py-2 min-w-[150px]')}>
            <div className="text-[9px] tracking-[0.3em] text-white/60">DISTANCIA</div>
            <div style={SERIF} className="text-3xl font-bold italic leading-none text-amber-200">{fmtDist(hud.dist)}</div>
            <div className="mt-1 flex items-center justify-between gap-3 text-xs">
              <span className="font-mono text-white/85">{hud.score.toLocaleString('es-ES')} pts</span>
              <span className="rounded bg-amber-400/20 px-1.5 text-[10px] text-amber-200">TRAMO {hud.level}</span>
            </div>
            {hud.combo > 1 && <div className="mt-1 text-[11px] font-bold text-rose-300">Combo anillos ×{hud.combo}</div>}
          </div>
          {hud.powers.map(p => {
            const Icon = POWER_ICON[p.kind], col = POWER_INFO[p.kind].color;
            return (
              <div key={p.kind} className={clsx(card, 'px-2 py-1 flex items-center gap-2 text-xs')}>
                <Icon size={14} style={{ color: col }} /><span>{POWER_INFO[p.kind].label}</span>
                <div className="ml-auto h-1.5 w-12 rounded-full bg-white/15 overflow-hidden"><div className="h-full rounded-full" style={{ width: `${(p.t / p.max) * 100}%`, background: col }} /></div>
              </div>
            );
          })}
        </div>

        <div className="absolute right-3 top-3 flex flex-col items-end gap-2">
          <div className="pointer-events-auto flex gap-2">
            <button aria-label="Silencio" onClick={onMute} className={clsx(card, 'h-9 w-9 grid place-items-center')}>{muted ? <VolumeX size={16} /> : <Volume2 size={16} />}</button>
            <button aria-label="Pausa" onClick={onPause} className={clsx(card, 'h-9 w-9 grid place-items-center')}><Pause size={16} /></button>
          </div>
          <div className={clsx(card, 'px-3 py-2 flex flex-col items-end gap-1')}>
            <div className="flex gap-1">{Array.from({ length: hud.maxHealth }).map((_, i) => <Heart key={i} size={16} className={i < hud.health ? 'text-rose-400 fill-rose-400' : 'text-white/25'} />)}</div>
            <div className="flex items-center gap-1 text-sm font-mono"><Star size={14} className="text-yellow-300 fill-yellow-300" />{hud.stars}</div>
            <div className="flex items-center gap-1">{[0, 1, 2].map(i => <Wind key={i} size={14} className={i < hud.boosts ? 'text-emerald-300' : 'text-white/20'} />)}</div>
          </div>
        </div>

        <div className="absolute left-3 top-1/2 -translate-y-1/2 flex items-center gap-2">
          <Vario v={hud.vario} lift={hud.inLift} />
          <div className="flex flex-col gap-2">
            <Gauge label="ALTITUD">
              <div className="font-mono text-lg font-bold leading-tight">{Math.round(hud.alt)} m</div>
              <div className={clsx('font-mono text-[11px]', hud.agl < 60 ? 'text-rose-300' : 'text-white/60')}>suelo {Math.round(hud.agl)} m</div>
            </Gauge>
            <Gauge label="VELOCIDAD"><div className="font-mono text-lg font-bold leading-tight">{Math.round(hud.speed)}<span className="text-xs text-white/60"> km/h</span></div></Gauge>
          </div>
        </div>

        {hud.thermalAngle !== null && (
          <div className="absolute bottom-5 left-1/2 -translate-x-1/2 flex flex-col items-center">
            <div className="h-12 w-12 rounded-full bg-[#1c1030]/50 ring-1 ring-amber-300/40 grid place-items-center">
              <Navigation2 size={22} className="text-amber-300 fill-amber-300/40" style={{ transform: `rotate(${hud.thermalAngle}rad)` }} />
            </div>
            <div className="mt-1 text-[11px] text-amber-100/90 drop-shadow">Térmica · {Math.round(hud.thermalDist)} m</div>
          </div>
        )}
        {hud.warn && <div className="absolute top-28 left-1/2 -translate-x-1/2 rounded-lg bg-rose-600/80 px-4 py-1.5 text-sm font-bold tracking-wide animate-pulse ring-1 ring-rose-200/60">{hud.warn}</div>}
      </>)}

      <div className="absolute top-3 left-1/2 -translate-x-1/2 flex flex-col items-center gap-1.5 w-[min(60%,420px)]">
        {msgs.map(m => (
          <div key={m.id} className={clsx('rounded-full px-4 py-1 text-sm font-semibold shadow-lg ring-1 text-center',
            m.kind === 'good' && 'bg-amber-400/85 text-[#2a1020] ring-amber-100/60', m.kind === 'bad' && 'bg-rose-600/85 ring-rose-200/50', m.kind === 'info' && 'bg-[#1c1030]/70 ring-white/20')}>
            {m.text}
          </div>
        ))}
      </div>
    </div>
  );
}

import { Bird, CircleDot, Star, Trophy, Volume2, VolumeX, Wind } from 'lucide-react';
import clsx from 'clsx';
import type { ReactNode } from 'react';
import { DIFFS, fmtDist } from '../game/config';
import type { DiffId, GameRecord } from '../game/config';

export const SERIF = { fontFamily: '"Iowan Old Style", "Palatino Linotype", Palatino, Georgia, "Times New Roman", serif' };

const KEYS: Array<[string, string]> = [['↑ ↓ / W S', 'Morro arriba / abajo'], ['← → / A D', 'Alabear y virar'], ['Espacio / Shift', 'Ráfaga de velocidad'], ['P / Esc', 'Pausa']];
const TIPS: Array<[ReactNode, string]> = [
  [<Wind key="w" size={15} className="text-amber-300" />, 'Vira en círculos dentro de las columnas doradas para subir'],
  [<CircleDot key="c" size={15} className="text-sky-300" />, 'Evita las columnas azules: el aire baja'],
  [<Bird key="b" size={15} className="text-rose-300" />, 'Esquiva gansos y halcones'],
  [<Star key="s" size={15} className="text-yellow-300" />, '8 estrellas = 1 ráfaga · anillos seguidos = combo'],
];

interface Props {
  diff: DiffId; setDiff: (d: DiffId) => void; invert: boolean; setInvert: (v: boolean) => void;
  records: Record<DiffId, GameRecord>; muted: boolean; onMute: () => void; onPlay: () => void;
}

export default function Menu({ diff, setDiff, invert, setInvert, records, muted, onMute, onPlay }: Props) {
  return (
    <div className="absolute inset-0 overflow-y-auto bg-gradient-to-r from-[#1c1030]/90 via-[#2a1430]/45 to-transparent text-white">
      <div className="min-h-full flex items-center p-4 sm:p-10">
        <div className="w-full max-w-[470px]">
          <div className="text-[11px] tracking-[0.55em] text-amber-200/80 uppercase">Vuelo sin motor</div>
          <h1 style={SERIF} className="mt-1 text-6xl sm:text-7xl italic font-bold leading-[0.95] bg-gradient-to-br from-amber-100 via-amber-300 to-rose-400 bg-clip-text text-transparent drop-shadow-[0_6px_30px_rgba(255,150,80,0.35)]">Planeador</h1>
          <div style={SERIF} className="text-lg italic text-rose-100/85 -mt-1">Valle Dorado</div>
          <p className="mt-3 text-sm text-white/75 leading-relaxed">
            El sol cae sobre un valle sin fin. Sin motor, solo el aire: cambia altura por velocidad, encuentra térmicas para
            volver a subir y llega más lejos que nadie antes de que se apague la luz.
          </p>
          <div className="mt-5 text-[10px] tracking-[0.35em] text-white/60 uppercase">Condiciones</div>
          <div className="mt-2 grid grid-cols-3 gap-2">
            {(Object.keys(DIFFS) as DiffId[]).map(id => (
              <button key={id} onClick={() => setDiff(id)} className={clsx('rounded-xl px-2.5 py-2 text-left ring-1 transition',
                diff === id ? 'bg-gradient-to-br from-amber-400/90 to-rose-500/90 ring-amber-100/70 shadow-[0_0_24px_rgba(255,160,80,0.45)]' : 'bg-white/5 ring-white/15 hover:bg-white/10')}>
                <div style={SERIF} className="font-bold italic text-lg leading-tight">{DIFFS[id].name}</div>
                <div className="text-[10px] leading-tight text-white/80">{DIFFS[id].desc}</div>
              </button>
            ))}
          </div>
          <div className="mt-3 flex items-center gap-3 rounded-xl bg-black/30 ring-1 ring-white/10 px-3 py-2">
            <Trophy className="text-amber-300 shrink-0" size={20} />
            <div className="text-xs text-white/70">Récord · {DIFFS[diff].name}</div>
            <div className="ml-auto text-right">
              <div className="font-mono text-lg font-bold text-amber-200 leading-tight">{fmtDist(records[diff].dist)}</div>
              <div className="font-mono text-[11px] text-white/60">{records[diff].score.toLocaleString('es-ES')} pts</div>
            </div>
          </div>
          <div className="mt-3 grid grid-cols-2 gap-x-3 gap-y-1">
            {KEYS.map(([k, d]) => (
              <div key={k} className="flex items-center gap-2 text-xs">
                <span className="rounded bg-white/10 ring-1 ring-white/15 px-1.5 py-0.5 font-mono text-[10px] text-amber-100 whitespace-nowrap">{k}</span>
                <span className="text-white/70">{d}</span>
              </div>
            ))}
          </div>
          <ul className="mt-3 space-y-1">{TIPS.map(([icon, t], i) => <li key={i} className="flex items-center gap-2 text-xs text-white/75">{icon}{t}</li>)}</ul>
          <div className="mt-4 flex items-center justify-between gap-3">
            <label className="flex items-center gap-2 text-xs text-white/80 cursor-pointer">
              <input type="checkbox" checked={invert} onChange={e => setInvert(e.target.checked)} className="accent-amber-500 h-4 w-4" /> Invertir eje vertical
            </label>
            <button aria-label="Silencio" onClick={onMute} className="h-8 w-8 grid place-items-center rounded-lg bg-white/10 ring-1 ring-white/20 hover:bg-white/20">
              {muted ? <VolumeX size={16} /> : <Volume2 size={16} />}
            </button>
          </div>
          <button onClick={onPlay} className="mt-5 w-full rounded-2xl py-3.5 text-xl font-bold tracking-wide bg-gradient-to-r from-amber-300 via-orange-400 to-rose-500 text-[#2a1020] shadow-[0_10px_40px_rgba(255,130,70,0.5)] hover:brightness-110 active:scale-[0.98] transition">
            <span style={SERIF} className="italic">Jugar</span>
          </button>
        </div>
      </div>
    </div>
  );
}

import { Clock, Home, Play, RotateCcw, Star, Target, Trophy } from 'lucide-react';
import type { ReactNode } from 'react';
import { DIFFS, fmtDist } from '../game/config';
import type { Summary } from '../game/config';
import { SERIF } from './Menu';

const btn = 'flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 font-semibold transition active:scale-[0.98]';
const primary = `${btn} bg-gradient-to-r from-amber-300 via-orange-400 to-rose-500 text-[#2a1020] shadow-[0_8px_30px_rgba(255,130,70,0.45)] hover:brightness-110`;
const ghost = `${btn} bg-white/10 ring-1 ring-white/20 hover:bg-white/20 text-white`;

const Panel = ({ children }: { children: ReactNode }) => (
  <div className="absolute inset-0 grid place-items-center bg-[#1c1030]/55 backdrop-blur-[2px] p-4 overflow-y-auto">
    <div className="w-full max-w-sm rounded-2xl bg-gradient-to-b from-[#2b1838]/95 to-[#1c1030]/95 ring-1 ring-amber-200/20 p-6 text-white shadow-2xl">{children}</div>
  </div>
);

export function PauseScreen({ onResume, onRestart, onMenu }: { onResume: () => void; onRestart: () => void; onMenu: () => void }) {
  return (
    <Panel>
      <h2 style={SERIF} className="text-4xl italic font-bold text-amber-200 text-center">Pausa</h2>
      <p className="mt-1 text-center text-sm text-white/65">El viento espera. Respira hondo.</p>
      <div className="mt-5 flex flex-col gap-2">
        <button onClick={onResume} className={primary}><Play size={18} /> Continuar</button>
        <button onClick={onRestart} className={ghost}><RotateCcw size={18} /> Reiniciar vuelo</button>
        <button onClick={onMenu} className={ghost}><Home size={18} /> Menú principal</button>
      </div>
    </Panel>
  );
}

const Stat = ({ icon, label, value }: { icon: ReactNode; label: string; value: string | number }) => (
  <div className="rounded-xl bg-white/5 ring-1 ring-white/10 px-3 py-2">
    <div className="flex items-center gap-1.5 text-[10px] tracking-widest text-white/55 uppercase">{icon}{label}</div>
    <div className="font-mono text-lg font-bold">{value}</div>
  </div>
);

export function GameOverScreen({ s, onRetry, onMenu }: { s: Summary; onRetry: () => void; onMenu: () => void }) {
  return (
    <Panel>
      <div className="text-center text-[11px] tracking-[0.4em] text-rose-200/80 uppercase">Fin del vuelo</div>
      <h2 style={SERIF} className="mt-1 text-center text-3xl italic font-bold text-amber-100">{s.reason}</h2>
      {s.newRecord && <div className="mt-3 mx-auto w-fit flex items-center gap-2 rounded-full bg-amber-400 px-3 py-1 text-sm font-bold text-[#2a1020] animate-bounce"><Trophy size={16} /> ¡Nuevo récord!</div>}
      <div className="mt-4 text-center">
        <div className="text-[10px] tracking-[0.35em] text-white/55">DISTANCIA</div>
        <div style={SERIF} className="text-5xl italic font-bold text-amber-300">{fmtDist(s.dist)}</div>
        <div className="font-mono text-white/80">{s.score.toLocaleString('es-ES')} puntos</div>
      </div>
      <div className="mt-4 grid grid-cols-2 gap-2">
        <Stat icon={<Star size={12} />} label="Estrellas" value={s.stars} />
        <Stat icon={<Target size={12} />} label="Anillos" value={s.rings} />
        <Stat icon={<Clock size={12} />} label="Tiempo" value={`${Math.floor(s.time / 60)}:${Math.floor(s.time % 60).toString().padStart(2, '0')}`} />
        <Stat icon={<Trophy size={12} />} label="Tramo" value={s.level} />
      </div>
      <div className="mt-3 text-center text-xs text-white/60">Récord {DIFFS[s.diff].name}: {fmtDist(s.best.dist)} · {s.best.score.toLocaleString('es-ES')} pts</div>
      <div className="mt-5 flex flex-col gap-2">
        <button onClick={onRetry} className={primary}><RotateCcw size={18} /> Volver a volar</button>
        <button onClick={onMenu} className={ghost}><Home size={18} /> Menú principal</button>
      </div>
    </Panel>
  );
}

import { useRef, useState } from 'react';
import type { PointerEvent } from 'react';
import { Wind } from 'lucide-react';
import type { Input } from '../game/input';

const R = 56;

/** Joystick virtual (cabeceo + alabeo) y botón de ráfaga para pantallas táctiles. */
export default function TouchControls({ input, onBoost }: { input: Input; onBoost: () => void }) {
  const base = useRef<HTMLDivElement>(null);
  const pid = useRef<number | null>(null);
  const [knob, setKnob] = useState({ x: 0, y: 0 });

  const move = (e: PointerEvent<HTMLDivElement>) => {
    if (pid.current !== e.pointerId || !base.current) return;
    const b = base.current.getBoundingClientRect();
    let dx = e.clientX - (b.left + b.width / 2), dy = e.clientY - (b.top + b.height / 2);
    const d = Math.hypot(dx, dy);
    if (d > R) { dx = (dx / d) * R; dy = (dy / d) * R; }
    setKnob({ x: dx, y: dy });
    Object.assign(input.touch, { active: true, x: dx / R, y: -dy / R });
  };
  const end = (e: PointerEvent<HTMLDivElement>) => {
    if (pid.current !== e.pointerId) return;
    pid.current = null; setKnob({ x: 0, y: 0 });
    Object.assign(input.touch, { active: false, x: 0, y: 0 });
  };

  return (<>
    <div ref={base} className="absolute bottom-6 left-6 h-36 w-36 rounded-full bg-[#1c1030]/40 ring-2 ring-amber-200/30 touch-none"
      onPointerDown={e => { pid.current = e.pointerId; e.currentTarget.setPointerCapture(e.pointerId); move(e); }}
      onPointerMove={move} onPointerUp={end} onPointerCancel={end}>
      <div className="pointer-events-none absolute left-1/2 top-1/2 h-14 w-14 -ml-7 -mt-7 rounded-full bg-gradient-to-br from-amber-200 to-rose-400 shadow-lg"
        style={{ transform: `translate(${knob.x}px, ${knob.y}px)` }} />
    </div>
    <button aria-label="Ráfaga" onPointerDown={e => { e.preventDefault(); onBoost(); }}
      className="absolute bottom-8 right-6 h-20 w-20 rounded-full bg-emerald-400/80 ring-2 ring-emerald-100/60 grid place-items-center text-[#10261c] font-bold touch-none active:scale-95">
      <div className="flex flex-col items-center text-xs"><Wind size={26} />Ráfaga</div>
    </button>
  </>);
}

/** Audio procedural con Web Audio: viento, variómetro, efectos y música ambiental suave. */
const CHORDS = [[146.8, 220.0, 277.2, 370.0], [130.8, 196.0, 246.9, 329.6], [110.0, 164.8, 220.0, 277.2], [123.5, 185.0, 246.9, 311.1]];

export class Sfx {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private windGain: GainNode | null = null; private windFilter: BiquadFilterNode | null = null;
  private music: GainNode | null = null; private noiseBuf: AudioBuffer | null = null;
  private varioNext = 0; private chordNext = 0; private chordIdx = 0;
  muted = false;

  unlock() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const AC = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (!AC) return;
    const ctx = (this.ctx = new AC());
    this.master = ctx.createGain(); this.master.gain.value = this.muted ? 0 : 0.8; this.master.connect(ctx.destination);
    this.noiseBuf = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate);
    const d = this.noiseBuf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    const src = ctx.createBufferSource(); src.buffer = this.noiseBuf; src.loop = true;
    this.windFilter = ctx.createBiquadFilter(); this.windFilter.type = 'bandpass'; this.windFilter.Q.value = 0.7;
    this.windGain = ctx.createGain(); this.windGain.gain.value = 0;
    src.connect(this.windFilter); this.windFilter.connect(this.windGain); this.windGain.connect(this.master); src.start();
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 900;
    this.music = ctx.createGain(); this.music.gain.value = 0.5; this.music.connect(lp); lp.connect(this.master);
  }

  setMuted(m: boolean) {
    this.muted = m;
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.8, this.ctx.currentTime, 0.05);
  }

  /** Cada fotograma: viento según velocidad, pitidos del variómetro y acordes de fondo. */
  tick(speed: number, vario: number, flying: boolean) {
    const ctx = this.ctx;
    if (!ctx || !this.windGain || !this.windFilter || !this.music) return;
    const now = ctx.currentTime, w = flying ? Math.min(1, speed / 55) : 0.15;
    this.windGain.gain.setTargetAtTime(0.05 + w * 0.22, now, 0.3);
    this.windFilter.frequency.setTargetAtTime(300 + w * 1300, now, 0.3);
    if (flying && now >= this.varioNext) {
      if (vario > 0.4) { this.tone(520 + vario * 95, 0.08, 'sine', 0.07); this.varioNext = now + 1 / (1.6 + vario * 0.9); }
      else if (vario < -3.5) { this.tone(190, 0.35, 'sine', 0.035, 160); this.varioNext = now + 0.9; }
    }
    if (now >= this.chordNext) {
      CHORDS[this.chordIdx++ % CHORDS.length].forEach((f, i) => {
        const t = now + i * 0.12, o = ctx.createOscillator(), g = ctx.createGain();
        o.type = 'triangle'; o.frequency.value = f; o.detune.value = Math.random() * 10 - 5;
        g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.03, t + 2.2); g.gain.linearRampToValueAtTime(0, t + 7.5);
        o.connect(g); g.connect(this.music as GainNode); o.start(t); o.stop(t + 7.6);
      });
      this.chordNext = now + 6.5;
    }
  }

  tone(freq: number, dur: number, type: OscillatorType, vol: number, slide?: number, delay = 0) {
    const ctx = this.ctx; if (!ctx || !this.master) return;
    const t = ctx.currentTime + delay, o = ctx.createOscillator(), g = ctx.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(slide, t + dur);
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol, t + 0.01); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master); o.start(t); o.stop(t + dur + 0.05);
  }

  noise(dur: number, vol: number, freq: number, type: BiquadFilterType = 'lowpass', sweep?: number) {
    const ctx = this.ctx; if (!ctx || !this.master || !this.noiseBuf) return;
    const t = ctx.currentTime, s = ctx.createBufferSource(), f = ctx.createBiquadFilter(), g = ctx.createGain();
    s.buffer = this.noiseBuf; f.type = type; f.frequency.setValueAtTime(freq, t);
    if (sweep) f.frequency.exponentialRampToValueAtTime(sweep, t + dur);
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    s.connect(f); f.connect(g); g.connect(this.master); s.start(t, Math.random()); s.stop(t + dur + 0.05);
  }

  private arp(base: number, steps: number[], dur: number, type: OscillatorType, vol: number, gap: number) {
    steps.forEach((s, i) => this.tone(base * Math.pow(2, s / 12), dur, type, vol, undefined, i * gap));
  }
  star() { this.arp(1320, [0, 7], 0.15, 'sine', 0.1, 0.06); }
  ring(combo: number) { this.arp(523 * Math.pow(2, combo / 12), [0, 4, 7, 12], 0.35, 'triangle', 0.1, 0.05); }
  power() { this.arp(440, [0, 5, 9, 14, 17], 0.25, 'sine', 0.09, 0.06); }
  level() { this.arp(392, [0, 7, 12, 16], 0.5, 'triangle', 0.08, 0.1); }
  hit() { this.noise(0.45, 0.5, 900); this.tone(110, 0.3, 'square', 0.12, 50); }
  boost() { this.noise(0.7, 0.35, 400, 'bandpass', 2400); }
  crash() { this.noise(1.4, 0.7, 1200, 'lowpass', 120); this.tone(90, 0.8, 'sawtooth', 0.12, 35); }
  warn() { this.arp(880, [0, 0], 0.09, 'square', 0.05, 0.14); }

  dispose() { this.ctx?.close().catch(() => undefined); this.ctx = null; }
}

import * as THREE from 'three';
import { lin } from './three-compat';
import { rnd } from './noise';

export type BirdKind = 'ganso' | 'halcon' | 'buitre';

export interface Bird {
  active: boolean; kind: BirdKind; g: THREE.Group; wl: THREE.Mesh; wr: THREE.Mesh; pos: THREE.Vector3; vel: THREE.Vector3;
  flap: number; rate: number; state: number; t: number; ox: number; oz: number; oy: number; or: number; ang: number; hit: boolean;
}

const look = new THREE.Vector3(), want = new THREE.Vector3();

/** Aves: bandadas de gansos en V, halcones que se lanzan en picado y buitres que giran en las térmicas. */
export class Birds {
  readonly list: Bird[] = []; private scene: THREE.Scene;
  private body = new THREE.ConeGeometry(0.38, 2.2, 5); private wing = new THREE.BufferGeometry();
  private mats: Record<BirdKind, THREE.MeshLambertMaterial> = {
    ganso: new THREE.MeshLambertMaterial({ color: lin('#3b3330'), side: THREE.DoubleSide }),
    halcon: new THREE.MeshLambertMaterial({ color: lin('#5a2c18'), emissive: lin('#2a0800'), side: THREE.DoubleSide }),
    buitre: new THREE.MeshLambertMaterial({ color: lin('#241a18'), side: THREE.DoubleSide }),
  };

  constructor(scene: THREE.Scene) {
    this.scene = scene;
    this.body.rotateX(-Math.PI / 2);
    this.wing.setAttribute('position', new THREE.BufferAttribute(new Float32Array([0, 0, -0.45, 0, 0, 0.5, 2.9, 0, 0.35, 0, 0, -0.45, 2.9, 0, 0.35, 2.6, 0, -0.05]), 3));
    this.wing.computeVertexNormals();
    for (let i = 0; i < 30; i++) {
      const g = new THREE.Group(), wr = new THREE.Mesh(this.wing, this.mats.ganso), wl = new THREE.Mesh(this.wing, this.mats.ganso);
      wl.scale.x = -1;
      g.add(new THREE.Mesh(this.body, this.mats.ganso), wl, wr);
      g.visible = false; scene.add(g);
      this.list.push({ active: false, kind: 'ganso', g, wl, wr, pos: new THREE.Vector3(), vel: new THREE.Vector3(), flap: Math.random() * 6, rate: 8, state: 0, t: 0, ox: 0, oz: 0, oy: 0, or: 0, ang: 0, hit: false });
    }
  }

  private take(kind: BirdKind, scale: number): Bird | null {
    const b = this.list.find(o => !o.active);
    if (!b) return null;
    Object.assign(b, { active: true, kind, hit: false, state: 0, t: 0 });
    b.g.scale.setScalar(scale); b.g.rotation.set(0, 0, 0); b.g.visible = true;
    b.g.children.forEach(c => { (c as THREE.Mesh).material = this.mats[kind]; });
    return b;
  }

  clear() { this.list.forEach(b => { b.active = false; b.g.visible = false; }); }

  /** Bandada en V que cruza el valle en dirección dir (±1 en X). */
  spawnGeese(x: number, y: number, z: number, dir: number, n = 7) {
    for (let i = 0; i < n; i++) {
      const b = this.take('ganso', 1.7);
      if (!b) return;
      const row = Math.ceil(i / 2), side = i % 2 ? 1 : -1;
      b.pos.set(x - dir * row * 5, y + rnd(-0.5, 0.5), z + side * row * 5.5);
      b.vel.set(dir * 14, 0, rnd(-1, 1)); b.rate = rnd(6.5, 7.5);
    }
  }

  spawnHawk(x: number, y: number, z: number) {
    const b = this.take('halcon', 2.1);
    if (b) Object.assign(b, { ox: x, oz: z, oy: y, or: 35, ang: Math.random() * 6, rate: 6 });
    if (b) b.pos.set(x + 35, y, z);
  }

  spawnVultures(cx: number, cz: number, y: number, r: number, n: number) {
    for (let i = 0; i < n; i++) {
      const b = this.take('buitre', 2.6);
      if (b) Object.assign(b, { ox: cx, oz: cz, oy: y + i * 18, or: r * rnd(0.4, 0.7), ang: (i / n) * 6.28, rate: 3 });
    }
  }

  update(dt: number, gp: THREE.Vector3, gv: THREE.Vector3) {
    for (const b of this.list) {
      if (!b.active) continue;
      b.t += dt;
      if (b.kind === 'ganso') b.flap += dt * b.rate;
      else if (b.kind === 'buitre') {
        b.ang += dt * 0.45;
        b.vel.set(-Math.sin(b.ang), 0, Math.cos(b.ang));
        b.pos.set(b.ox + Math.cos(b.ang) * b.or, b.oy + Math.sin(b.t * 0.3) * 5, b.oz + Math.sin(b.ang) * b.or);
        b.flap += dt * (Math.sin(b.t) > 0.7 ? 5 : 0.4);
      } else if (b.state === 0) {
        b.ang += dt * 0.8;
        want.set(b.ox + Math.cos(b.ang) * b.or, b.oy, b.oz + Math.sin(b.ang) * b.or);
        b.vel.subVectors(want, b.pos).multiplyScalar(2);
        if (b.pos.distanceTo(gp) < 230) { b.state = 1; b.t = 0; }
        b.flap += dt * 4;
      } else if (b.state === 1) {
        want.copy(gp).addScaledVector(gv, 0.6).sub(b.pos).normalize().multiplyScalar(30);
        b.vel.lerp(want, Math.min(1, dt * 1.6));
        b.flap += dt * 10;
        if (b.t > 7 || b.hit) { b.state = 2; b.t = 0; }
      } else {
        b.vel.y += dt * 10; b.flap += dt * 9;
        if (b.t > 6) { b.active = false; b.g.visible = false; continue; }
      }
      const falling = b.hit && b.kind === 'ganso';
      if (falling) { b.vel.y -= dt * 18; b.g.rotation.z += dt * 6; }
      if (b.kind !== 'buitre') b.pos.addScaledVector(b.vel, dt);
      b.g.position.copy(b.pos);
      if (!falling) { look.copy(b.pos).sub(b.vel); b.g.lookAt(look); }
      b.wr.rotation.z = Math.sin(b.flap) * 0.65; b.wl.rotation.z = -b.wr.rotation.z;
    }
  }

  /** Primera ave peligrosa que toca la esfera (p, r). */
  collide(p: THREE.Vector3, r: number): Bird | null {
    for (const b of this.list) {
      if (!b.active || b.hit || b.kind === 'buitre') continue;
      const rr = r + b.g.scale.x * 1.4;
      if (b.pos.distanceToSquared(p) < rr * rr) return b;
    }
    return null;
  }

  diving(p: THREE.Vector3): boolean {
    return this.list.some(b => b.active && b.kind === 'halcon' && b.state === 1 && b.pos.distanceTo(p) < 160);
  }

  despawn(px: number, pz: number) {
    this.list.forEach(b => { if (b.active && (b.pos.z - pz > 420 || Math.hypot(b.pos.x - px, b.pos.z - pz) > 1300)) { b.active = false; b.g.visible = false; } });
  }

  dispose() {
    this.list.forEach(b => this.scene.remove(b.g)); this.body.dispose(); this.wing.dispose();
    Object.values(this.mats).forEach(m => m.dispose());
  }
}

/** Configuración, tipos compartidos y récords del Planeador. */

/** Atmósfera del atardecer (compartida por cielo, agua y niebla). */
export const SUN_DIR: [number, number, number] = [-0.55, 0.15, -0.82];
export const FOG_HEX = '#d9906a', FOG_NEAR = 150, FOG_FAR = 920;

export type DiffId = 'facil' | 'normal' | 'experto';
/** sink: descendencia base (m/s) · thermal: prob. de térmica por tramo · lift/birds: multiplicadores. */
export interface DiffCfg { name: string; desc: string; sink: number; thermal: number; lift: number; birds: number; health: number; alt: number }

export const DIFFS: Record<DiffId, DiffCfg> = {
  facil: { name: 'Brisa', desc: 'Térmicas generosas y cielo tranquilo', sink: 0.35, thermal: 0.8, lift: 1.25, birds: 0.6, health: 4, alt: 240 },
  normal: { name: 'Valle', desc: 'El vuelo equilibrado de siempre', sink: 0.75, thermal: 0.62, lift: 1.0, birds: 1, health: 3, alt: 220 },
  experto: { name: 'Tormenta', desc: 'Descendencias, halcones y poca ayuda', sink: 1.15, thermal: 0.48, lift: 0.88, birds: 1.5, health: 2, alt: 200 },
};

export type PowerKind = 'viento' | 'escudo' | 'iman' | 'reparar';
export const POWER_INFO: Record<PowerKind, { label: string; color: string; dur: number }> = {
  viento: { label: 'Viento de cola', color: '#7cf0c8', dur: 9 },
  escudo: { label: 'Escudo', color: '#6fc8ff', dur: 10 },
  iman: { label: 'Imán de estrellas', color: '#ff7ad9', dur: 12 },
  reparar: { label: 'Reparación', color: '#9dff6a', dur: 0 },
};

export type MsgKind = 'good' | 'bad' | 'info';

export interface HudData {
  alt: number; agl: number; vario: number; speed: number; dist: number; score: number; stars: number; rings: number;
  health: number; maxHealth: number; level: number; boosts: number; powers: { kind: PowerKind; t: number; max: number }[];
  warn: string | null; thermalAngle: number | null; thermalDist: number; inLift: boolean; combo: number;
}

export interface GameRecord { dist: number; score: number }
export interface Summary {
  dist: number; score: number; stars: number; rings: number; time: number;
  level: number; reason: string; newRecord: boolean; diff: DiffId; best: GameRecord;
}

const REC_KEY = 'planeador-records';

export function loadRecords(): Record<DiffId, GameRecord> {
  const out = { facil: { dist: 0, score: 0 }, normal: { dist: 0, score: 0 }, experto: { dist: 0, score: 0 } };
  try {
    const r = JSON.parse(localStorage.getItem(REC_KEY) || '{}');
    (Object.keys(out) as DiffId[]).forEach(k => { if (r[k]) out[k] = { dist: r[k].dist || 0, score: r[k].score || 0 }; });
  } catch { /* sin almacenamiento */ }
  return out;
}

/** Guarda el récord; devuelve true si se superó la distancia o la puntuación. */
export function saveRecord(diff: DiffId, dist: number, score: number): boolean {
  const all = loadRecords(), cur = all[diff];
  if (dist <= cur.dist && score <= cur.score) return false;
  all[diff] = { dist: Math.max(dist, cur.dist), score: Math.max(score, cur.score) };
  try { localStorage.setItem(REC_KEY, JSON.stringify(all)); } catch { /* sin almacenamiento */ }
  return true;
}

export const fmtDist = (m: number) => (m >= 1000 ? `${(m / 1000).toFixed(2)} km` : `${Math.floor(m)} m`);

import { DIFFS } from './config';
import type { DiffId, PowerKind } from './config';
import type { Birds } from './birds';
import type { Glider } from './glider';
import type { Pickups } from './pickups';
import type { Thermals } from './thermals';
import { groundAt, riverX, valleyYaw } from './terrain';
import { clamp, rnd } from './noise';

const KINDS: PowerKind[] = ['viento', 'escudo', 'iman', 'reparar'];

/** Genera el contenido del valle por tramos delante del planeador y retira lo que queda atrás. */
export class Director {
  private nextZ = 0; private checkT = 0;
  private th: Thermals; private pk: Pickups; private birds: Birds;
  constructor(th: Thermals, pk: Pickups, birds: Birds) { this.th = th; this.pk = pk; this.birds = birds; }

  clearAll() { this.th.clear(); this.pk.clear(); this.birds.clear(); }

  /** Escena del menú: térmicas con buitres alrededor del planeador que gira. */
  menuScene(cx: number, cz: number, y: number) {
    this.clearAll();
    this.th.spawn(cx, cz, 48, 5, y + 260);
    this.th.spawn(cx + 240, cz - 380, 40, 4, y + 260);
    this.th.spawn(cx - 260, cz - 620, 44, 4, y + 260);
    this.birds.spawnVultures(cx, cz, y - 25, 80, 3);
    this.birds.spawnGeese(cx - 160, y + 40, cz - 120, 1);
    for (let i = 0; i < 8; i++) { const a = (i / 8) * Math.PI * 2; this.pk.spawnStar(cx + Math.cos(a) * 95, y + 8 + Math.sin(a * 2) * 6, cz + Math.sin(a) * 95); }
    this.th.list.forEach(t => { t.age = 2; });
  }

  /** Arranque de partida: estrellas, anillos, térmica y bandada justo delante. */
  opening(g: Glider) {
    this.clearAll();
    const p = g.pos, at = (d: number, side = 0) => ({ x: p.x + g.hfwd.x * d + g.right.x * side, z: p.z + g.hfwd.z * d + g.right.z * side });
    for (let i = 0; i < 7; i++) { const q = at(22 + i * 9, Math.sin(i * 0.7) * 5); this.pk.spawnStar(q.x, p.y - 1 - i * 0.6, q.z); }
    [95, 135, 175].forEach((d, i) => { const q = at(d, -6 + i * 5); this.pk.spawnRing(q.x, p.y - 5 - i * 3, q.z, valleyYaw(q.z)); });
    const t1 = at(150, 55), t2 = at(420, -80), gs = at(120, -70), pw = at(240, 10);
    this.th.spawn(t1.x, t1.z, 50, 6.5, p.y + 300); this.th.spawn(t2.x, t2.z, 46, 6, p.y + 300);
    this.birds.spawnVultures(t1.x, t1.z, p.y + 20, 50, 2);
    this.birds.spawnGeese(gs.x, p.y + 6, gs.z, g.right.x >= 0 ? 1 : -1, 5);
    this.pk.spawnPower(pw.x, p.y - 12, pw.z, 'viento');
    this.th.list.forEach(t => { t.age = 2; }); this.nextZ = p.z - 260;
  }

  update(dt: number, g: Glider, level: number, diff: DiffId) {
    const p = g.pos;
    while (this.nextZ > p.z - 950) { this.segment(this.nextZ, p.y, level, diff); this.nextZ -= 95 + Math.random() * 60; }
    if ((this.checkT -= dt) > 0) return;
    this.checkT = 1;
    const n = this.th.nearest(p);
    if (!n || n.d > 520) {
      const d = rnd(260, 380), s = rnd(-120, 120);
      this.th.spawn(p.x + g.hfwd.x * d + g.right.x * s, p.z + g.hfwd.z * d + g.right.z * s, rnd(36, 52), rnd(4.2, 6.5) * DIFFS[diff].lift, rnd(480, 600));
    }
    this.th.despawn(p.x, p.z); this.pk.despawn(p.x, p.z); this.birds.despawn(p.x, p.z);
  }

  private segment(z: number, py: number, L: number, diff: DiffId) {
    const D = DIFFS[diff], cx = riverX(z), refY = clamp(py, 90, 430), r = Math.random;
    if (r() < D.thermal * (1 - Math.min(0.35, (L - 1) * 0.05))) {
      const x = cx + (r() - 0.5) * 320, t = this.th.spawn(x, z, rnd(34, 56), rnd(4.2, 7.2) * D.lift, rnd(470, 620));
      if (t && r() < 0.4) this.birds.spawnVultures(x, z, refY + rnd(-20, 60), t.r, 2);
    }
    if (r() < (0.1 + L * 0.03) * D.birds) this.th.spawn(cx + (r() - 0.5) * 380, z, rnd(40, 60), -(2.4 + L * 0.3) * D.birds, rnd(450, 600));
    const roll = r(), off = (r() - 0.5) * 200, y0 = refY + (r() - 0.5) * 40;
    if (roll < 0.32) {
      for (let i = 0; i < 3; i++) {
        const zz = z - i * 30, xx = riverX(zz) + off;
        this.pk.spawnRing(xx, Math.max(y0 - i * 4, groundAt(xx, zz) + 35), zz, valleyYaw(zz));
      }
    } else if (roll < 0.74) {
      const curve = (r() - 0.5) * 60;
      for (let i = 0; i < 6; i++) {
        const zz = z - i * 14, k = Math.sin(i / 5 * Math.PI), xx = riverX(zz) + off + k * curve;
        this.pk.spawnStar(xx, Math.max(y0 + k * 10, groundAt(xx, zz) + 25), zz);
      }
    }
    if (r() < (0.14 + L * 0.035) * D.birds) {
      const dir = r() < 0.5 ? 1 : -1;
      this.birds.spawnGeese(cx - dir * rnd(140, 260), refY + rnd(-25, 25), z, dir, 5 + Math.floor(r() * 4));
    }
    if (L >= 2 && r() < (0.05 + L * 0.025) * D.birds) this.birds.spawnHawk(cx + (r() - 0.5) * 200, refY + rnd(10, 50), z);
    if (r() < 0.08) {
      const x = cx + (r() - 0.5) * 200;
      this.pk.spawnPower(x, Math.max(refY + rnd(-30, 20), groundAt(x, z) + 30), z, KINDS[Math.floor(r() * KINDS.length)]);
    }
  }
}

import * as THREE from 'three';
import { glowTexture } from './textures';

const N = 600, TRAIL = 14;

interface Trail { line: THREE.Line; geo: THREE.BufferGeometry; pos: Float32Array; col: Float32Array }

/** Partículas (chispas, plumas, restos) y estelas cortas de vórtice en las puntas de ala. */
export class Effects {
  private scene: THREE.Scene;
  private geo = new THREE.BufferGeometry();
  private tex = glowTexture(64, 0.2);
  private mat = new THREE.PointsMaterial({ size: 3.2, map: this.tex, vertexColors: true, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, fog: false });
  private points = new THREE.Points(this.geo, this.mat);
  private pos = new Float32Array(N * 3); private col = new Float32Array(N * 3); private base = new Float32Array(N * 3);
  private vel = new Float32Array(N * 3); private life = new Float32Array(N); private max = new Float32Array(N); private grav = new Float32Array(N);
  private next = 0; private trails: Trail[] = [];
  private tmat = new THREE.LineBasicMaterial({ vertexColors: true, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, fog: false });

  constructor(scene: THREE.Scene) {
    this.scene = scene;
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    this.geo.setAttribute('color', new THREE.BufferAttribute(this.col, 3));
    this.points.frustumCulled = false; scene.add(this.points);
    for (let k = 0; k < 2; k++) {
      const geo = new THREE.BufferGeometry(), pos = new Float32Array(TRAIL * 3), col = new Float32Array(TRAIL * 3);
      geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
      geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
      const line = new THREE.Line(geo, this.tmat);
      line.frustumCulled = false; scene.add(line);
      this.trails.push({ line, geo, pos, col });
    }
  }

  /** Explosión de n partículas en p con color c. */
  burst(p: THREE.Vector3, c: THREE.Color, n: number, speed: number, life: number, gravity = 0) {
    for (let k = 0; k < n; k++) {
      const i = this.next, j = i * 3;
      this.next = (this.next + 1) % N;
      const u = Math.random() * 2 - 1, a = Math.random() * Math.PI * 2, s = Math.sqrt(1 - u * u), v = speed * (0.3 + Math.random() * 0.7);
      this.pos[j] = p.x; this.pos[j + 1] = p.y; this.pos[j + 2] = p.z;
      this.vel[j] = Math.cos(a) * s * v; this.vel[j + 1] = u * v; this.vel[j + 2] = Math.sin(a) * s * v;
      this.base[j] = c.r; this.base[j + 1] = c.g; this.base[j + 2] = c.b;
      this.life[i] = this.max[i] = life * (0.6 + Math.random() * 0.6);
      this.grav[i] = gravity;
    }
  }

  /** Estelas: cada punto sigue al anterior a 0,8 m, así la longitud no depende de los fps. */
  updateTrails(a: THREE.Vector3, b: THREE.Vector3, alpha: number, reset = false) {
    [a, b].forEach((p, k) => {
      const t = this.trails[k], q = t.pos;
      q[0] = p.x; q[1] = p.y; q[2] = p.z;
      for (let j = 3; j < TRAIL * 3; j += 3) {
        const dx = q[j - 3] - q[j], dy = q[j - 2] - q[j + 1], dz = q[j - 1] - q[j + 2], d = Math.hypot(dx, dy, dz);
        const f = reset ? 1 : d > 0.8 ? (d - 0.8) / d : 0;
        q[j] += dx * f; q[j + 1] += dy * f; q[j + 2] += dz * f;
      }
      for (let i = 0; i < TRAIL; i++) { const c = (1 - i / TRAIL) * alpha; t.col[i * 3] = c; t.col[i * 3 + 1] = c * 0.86; t.col[i * 3 + 2] = c * 0.72; }
      (t.geo.getAttribute('position') as THREE.BufferAttribute).needsUpdate = true;
      (t.geo.getAttribute('color') as THREE.BufferAttribute).needsUpdate = true;
    });
  }

  update(dt: number) {
    const drag = 1 - dt * 1.2;
    for (let i = 0; i < N; i++) {
      const j = i * 3;
      if (this.life[i] <= 0) { this.col[j] = this.col[j + 1] = this.col[j + 2] = 0; continue; }
      this.life[i] -= dt;
      this.vel[j + 1] -= this.grav[i] * dt;
      for (let a = 0; a < 3; a++) { this.vel[j + a] *= drag; this.pos[j + a] += this.vel[j + a] * dt; }
      const f = Math.max(0, this.life[i] / this.max[i]);
      for (let a = 0; a < 3; a++) this.col[j + a] = this.base[j + a] * f;
    }
    (this.geo.getAttribute('position') as THREE.BufferAttribute).needsUpdate = true;
    (this.geo.getAttribute('color') as THREE.BufferAttribute).needsUpdate = true;
  }

  clear() { this.life.fill(0); }
  dispose() {
    this.scene.remove(this.points);
    this.trails.forEach(t => { this.scene.remove(t.line); t.geo.dispose(); });
    this.geo.dispose(); this.mat.dispose(); this.tmat.dispose(); this.tex.dispose();
  }
}

import * as THREE from 'three';
import { DIFFS, POWER_INFO, loadRecords, saveRecord } from './config';
import type { DiffId, HudData, MsgKind, PowerKind, Summary } from './config';
import { setupRenderer, lin } from './three-compat';
import { Sky } from './sky';
import { Terrain, groundAt, heightAt, riverX, valleyYaw } from './terrain';
import { Thermals } from './thermals';
import { Pickups } from './pickups';
import { Birds } from './birds';
import { Effects } from './effects';
import { Glider } from './glider';
import { Director } from './director';
import { Input } from './input';
import { Sfx } from './audio';

export type Mode = 'menu' | 'play' | 'paused' | 'crash' | 'over';
export interface GameCallbacks { onHud: (h: HudData) => void; onMessage: (text: string, kind: MsgKind) => void; onGameOver: (s: Summary) => void }

const GOLD = lin('#ffc04a'), WHITE = new THREE.Color(1, 0.95, 0.88), BLUE = lin('#7fd0ff');
const FEATHER = new THREE.Color(0.75, 0.62, 0.52), SPLASH = new THREE.Color(0.75, 0.85, 1);
const TIMED: PowerKind[] = ['viento', 'escudo', 'iman'];

interface Run {
  dist: number; bonus: number; stars: number; rings: number; health: number; maxHealth: number; boosts: number; level: number;
  time: number; combo: number; comboT: number; invuln: number; crashT: number; reason: string; pw: Record<PowerKind, number>;
}

/** Orquesta escena, física, contenido, cámara, audio y HUD del Planeador. */
export class Game {
  readonly input = new Input(); readonly sfx = new Sfx();
  mode: Mode = 'menu';
  private cb: GameCallbacks; private container: HTMLElement;
  private renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' }); private scene = new THREE.Scene();
  private camera = new THREE.PerspectiveCamera(60, 1, 0.5, 2600);
  private ro: ResizeObserver;
  private raf = 0; private last = performance.now(); private time = 0;
  private sky = new Sky(this.scene); private terrain = new Terrain(this.scene); private thermals = new Thermals(this.scene);
  private pickups = new Pickups(this.scene); private birds = new Birds(this.scene); private fx = new Effects(this.scene);
  private glider = new Glider(this.scene); private director = new Director(this.thermals, this.pickups, this.birds);
  private diff: DiffId = 'normal'; private run = this.freshRun('normal');
  private camBase = new THREE.Vector3(); private camLook = new THREE.Vector3();
  private shake = 0; private hudT = 0; private warnT = 0; private varioS = 0; private menuAng = 0;
  private menuC = { x: 0, z: -200, y: 205 };
  private prev = new THREE.Vector3(); private tmp = new THREE.Vector3(); private tmp2 = new THREE.Vector3();

  constructor(container: HTMLElement, cb: GameCallbacks) {
    this.container = container; this.cb = cb;
    setupRenderer(this.renderer); this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.renderer.domElement.style.display = 'block'; container.appendChild(this.renderer.domElement);
    this.input.onBoost = () => this.boost();
    this.ro = new ResizeObserver(() => this.resize()); this.ro.observe(container);
    this.resize(); this.toMenu();
    this.raf = requestAnimationFrame(this.loop);
  }

  private freshRun(diff: DiffId): Run {
    const h = DIFFS[diff].health;
    return { dist: 0, bonus: 0, stars: 0, rings: 0, health: h, maxHealth: h, boosts: 1, level: 1, time: 0, combo: 0, comboT: 0,
      invuln: 0, crashT: 0, reason: '', pw: { viento: 0, escudo: 0, iman: 0, reparar: 0 } };
  }

  private resize() {
    const w = Math.max(1, this.container.clientWidth), h = Math.max(1, this.container.clientHeight);
    this.renderer.setSize(w, h);
    this.camera.aspect = w / h; this.camera.updateProjectionMatrix();
  }

  toMenu() {
    const c = this.menuC;
    this.mode = 'menu';
    c.x = riverX(c.z) - 20; c.y = groundAt(c.x, c.z) + 200;
    this.director.menuScene(c.x, c.z, c.y);
    this.glider.orbit(c.x, c.z, 70, c.y, this.menuAng);
    this.glider.shield.visible = false; this.glider.group.visible = true;
    this.terrain.update(c.x, c.z, c.x, c.z, 0, true);
    this.fx.clear(); this.trails(0, true);
    this.menuCamera(0);
    this.sky.place(this.camera.position, true);
  }

  start(diff: DiffId) {
    this.diff = diff; this.run = this.freshRun(diff);
    const x = riverX(0);
    this.glider.reset(x, DIFFS[diff].alt, 0, valleyYaw(0), 27);
    this.terrain.update(x, 0, x, 0, this.time, true);
    this.director.opening(this.glider);
    this.fx.clear(); this.trails(0, true); this.updateCamera(0, true);
    this.sky.place(this.camera.position, true); this.input.reset();
    this.varioS = 0; this.shake = 0; this.hudT = 0;
    this.mode = 'play'; this.last = performance.now(); this.sfx.unlock();
    this.cb.onMessage('Busca las columnas doradas: son térmicas que te elevan', 'info');
  }

  pause() { if (this.mode === 'play') { this.mode = 'paused'; this.input.reset(); } }
  resume() { if (this.mode === 'paused') { this.mode = 'play'; this.last = performance.now(); } }
  setMuted(m: boolean) { this.sfx.setMuted(m); }

  private boost() {
    if (this.mode !== 'play') return;
    const r = this.run, g = this.glider;
    if (r.boosts <= 0) { this.cb.onMessage('Sin ráfagas: recoge 8 estrellas', 'bad'); return; }
    r.boosts--;
    g.speed = Math.min(72, g.speed + 15); g.pitch = Math.max(g.pitch, 0.05);
    this.shake = Math.max(this.shake, 0.35);
    this.fx.burst(g.pos, WHITE, 40, 16, 0.8);
    this.sfx.boost();
  }

  private loop = () => {
    this.raf = requestAnimationFrame(this.loop);
    const now = performance.now(), dt = Math.min(0.05, Math.max(0, (now - this.last) / 1000));
    this.last = now;
    if (this.mode !== 'paused') {
      this.time += dt;
      this.input.update();
      if (this.mode === 'menu') this.stepMenu(dt); else if (this.mode === 'play') this.stepPlay(dt); else this.stepCrash(dt);
      const g = this.glider.pos, cam = this.camera.position;
      this.thermals.update(dt, this.time, cam);
      this.birds.update(dt, g, this.glider.vel);
      this.fx.update(dt);
      this.sky.update(cam, dt);
      this.terrain.update(g.x, g.z, cam.x, cam.z, this.time);
    }
    this.renderer.render(this.scene, this.camera);
  };

  private stepMenu(dt: number) {
    const c = this.menuC;
    this.menuAng += dt * 0.3;
    this.glider.orbit(c.x, c.z, 70, c.y, this.menuAng);
    this.trails(0.5);
    this.pickups.updateStars(dt, this.time, this.tmp.set(0, -9999, 0), false);
    this.menuCamera(dt);
    this.sfx.tick(20, 0, false);
  }

  /** Plano de portada: mirando hacia el sol, con la térmica y el planeador en el tercio derecho. */
  private menuCamera(dt: number) {
    const c = this.menuC, s = this.sky.sun, a = Math.atan2(s.z, s.x) + Math.PI + 0.3 + Math.sin(this.time * 0.08) * 0.25;
    this.camBase.set(c.x + Math.cos(a) * 230, 0, c.z + Math.sin(a) * 230);
    this.camBase.y = Math.max(c.y + 30, groundAt(this.camBase.x, this.camBase.z) + 25);
    const fx = c.x - this.camBase.x, fz = c.z - this.camBase.z, n = Math.hypot(fx, fz);
    this.camLook.set(c.x + (fz / n) * 100, c.y - 5, c.z - (fx / n) * 100);
    this.applyCamera(dt, 0);
  }

  private stepPlay(dt: number) {
    const g = this.glider, r = this.run, D = DIFFS[this.diff];
    r.time += dt;
    this.prev.copy(g.pos);
    let lift = this.thermals.liftAt(g.pos) - (D.sink + (r.level - 1) * 0.08);
    if (g.pos.y > 640) lift -= (g.pos.y - 640) * 0.06;
    if (r.pw.viento > 0) lift += 0.6;
    g.update(dt, this.input.state, lift, r.pw.viento > 0 ? 9 : 0);
    this.varioS += (g.vy - this.varioS) * Math.min(1, dt * 3);
    const h = heightAt(g.pos.x, g.pos.z), ground = Math.max(h, 0);
    if (g.pos.y < ground + 1.2) { this.crash(h < 0.5 ? 'Amerizaje forzoso en el río' : 'Te estrellaste contra la ladera'); return; }

    for (const p of this.pickups.updateRings(dt, this.prev, g.pos)) {
      r.rings++; r.combo = r.comboT > 0 ? Math.min(r.combo + 1, 9) : 1; r.comboT = 7;
      r.bonus += 100 * r.combo; g.speed = Math.min(72, g.speed + 3);
      this.fx.burst(p, GOLD, 50, 22, 1); this.sfx.ring(r.combo);
      this.cb.onMessage(r.combo > 1 ? `¡Anillo! Combo ×${r.combo}` : '¡Anillo! +100', 'good');
    }
    for (const p of this.pickups.updateStars(dt, this.time, g.pos, r.pw.iman > 0)) {
      r.stars++; r.bonus += 25;
      this.fx.burst(p, GOLD, 14, 10, 0.6); this.sfx.star();
      if (r.stars % 8 === 0 && r.boosts < 3) { r.boosts++; this.cb.onMessage('¡Ráfaga lista! Pulsa Espacio', 'good'); }
    }
    const pk = this.pickups.updatePowers(this.time, g.pos);
    if (pk) {
      if (pk === 'reparar') r.health = Math.min(r.maxHealth, r.health + 1); else r.pw[pk] = POWER_INFO[pk].dur;
      this.fx.burst(g.pos, lin(POWER_INFO[pk].color), 50, 15, 1); this.sfx.power();
      this.cb.onMessage(`${POWER_INFO[pk].label}${pk === 'reparar' ? ' +1' : ''}`, 'good');
    }

    if (r.invuln > 0) r.invuln -= dt;
    const b = this.birds.collide(g.pos, 3.5);
    if (b) {
      b.hit = true;
      if (r.pw.escudo > 0) {
        r.bonus += 50; this.fx.burst(b.pos, BLUE, 30, 14, 0.8); this.sfx.tone(660, 0.2, 'triangle', 0.1, 990);
        this.cb.onMessage('¡El escudo te protege! +50', 'good');
      } else if (r.invuln <= 0) {
        r.health--; r.invuln = 1.2; this.shake = 1; g.speed = Math.max(12, g.speed - 5);
        this.fx.burst(b.pos, FEATHER, 40, 9, 1.4, 4); this.sfx.hit();
        this.cb.onMessage(b.kind === 'halcon' ? '¡Te atacó un halcón!' : '¡Choque con un ganso!', 'bad');
        if (r.health <= 0) { this.crash('El planeador quedó destrozado'); return; }
      }
    }
    TIMED.forEach(k => { r.pw[k] = Math.max(0, r.pw[k] - dt); });
    if (r.comboT > 0 && (r.comboT -= dt) <= 0) r.combo = 0;

    r.dist = Math.max(r.dist, -g.pos.z);
    const lvl = 1 + Math.floor(r.dist / 1200);
    if (lvl > r.level) {
      r.level = lvl; r.bonus += 250; this.sfx.level();
      this.cb.onMessage(`Tramo ${lvl} · el aire se vuelve más exigente`, 'info');
    }
    this.director.update(dt, g, r.level, this.diff);

    g.shield.visible = r.pw.escudo > 0;
    (g.shield.material as THREE.MeshBasicMaterial).opacity = 0.12 + Math.sin(this.time * 6) * 0.05;
    g.group.visible = r.invuln <= 0 || Math.floor(this.time * 12) % 2 === 0;
    this.trails(0.25 + Math.min(0.55, g.speed / 90) + (r.pw.viento > 0 ? 0.3 : 0));
    if (lift > 1.5 && Math.random() < dt * 14) {
      this.fx.burst(this.tmp.set(g.pos.x + (Math.random() - 0.5) * 30, g.pos.y - 5, g.pos.z + (Math.random() - 0.5) * 30), GOLD, 1, 3, 1.4, -4);
    }
    const agl = g.pos.y - ground;
    const warn = g.stall ? '¡PÉRDIDA! Baja el morro' : agl < 45 ? '¡TERRENO! Gana altura' : this.birds.diving(g.pos) ? '¡Halcón en picado!' : null;
    if (warn && (this.warnT -= dt) <= 0) { this.sfx.warn(); this.warnT = 1.2; }
    this.updateCamera(dt);
    this.sfx.tick(g.speed, this.varioS, true);
    if ((this.hudT -= dt) <= 0) { this.hudT = 0.1; this.emitHud(agl, warn, lift > 0.5); }
  }

  private crash(reason: string) {
    const g = this.glider;
    this.mode = 'crash'; this.run.reason = reason; this.run.crashT = 0; this.shake = 1.6;
    this.fx.burst(g.pos, WHITE, 70, 20, 1.6, 9);
    this.fx.burst(g.pos, reason.includes('río') ? SPLASH : FEATHER, 60, 14, 1.8, 12);
    this.sfx.crash();
  }

  private stepCrash(dt: number) {
    const g = this.glider, r = this.run;
    g.crashStep(dt, groundAt(g.pos.x, g.pos.z));
    r.crashT += dt; this.menuAng += dt * 0.15;
    this.camBase.lerp(this.tmp.set(Math.cos(this.menuAng) * 40, 22, Math.sin(this.menuAng) * 40).add(g.pos), 1 - Math.exp(-dt * 1.5));
    this.camLook.lerp(g.pos, 1 - Math.exp(-dt * 3));
    this.applyCamera(dt, 0);
    this.sfx.tick(0, 0, false);
    if (this.mode === 'crash' && r.crashT > 1.8) {
      this.mode = 'over';
      const dist = Math.floor(r.dist), score = dist + r.bonus, newRecord = saveRecord(this.diff, dist, score);
      this.cb.onGameOver({ dist, score, stars: r.stars, rings: r.rings, time: r.time, level: r.level, reason: r.reason, newRecord, diff: this.diff, best: loadRecords()[this.diff] });
    }
  }

  private trails(alpha: number, reset = false) {
    this.glider.group.updateMatrixWorld();
    this.glider.tipL.getWorldPosition(this.tmp); this.glider.tipR.getWorldPosition(this.tmp2);
    this.fx.updateTrails(this.tmp, this.tmp2, alpha, reset);
  }

  /** Cámara de persecución: detrás, algo por encima y desplazada hacia el lado del viraje. */
  private updateCamera(dt: number, snap = false) {
    const g = this.glider, c = this.camBase;
    this.tmp.copy(g.pos).addScaledVector(g.hfwd, -17).addScaledVector(g.right, g.bank * 5).y += 5.5;
    c.lerp(this.tmp, snap ? 1 : 1 - Math.exp(-dt * 5));
    c.y = Math.max(c.y, groundAt(c.x, c.z) + 4);
    this.tmp.copy(g.pos).addScaledVector(g.hfwd, 22).y += 1.5 + g.fwd.y * 12;
    this.camLook.lerp(this.tmp, snap ? 1 : 1 - Math.exp(-dt * 6));
    const fov = 60 + Math.max(0, g.speed - 25) * 0.3;
    if (Math.abs(this.camera.fov - fov) > 0.1) { this.camera.fov += (fov - this.camera.fov) * Math.min(1, dt * 2); this.camera.updateProjectionMatrix(); }
    this.applyCamera(dt, g.bank * 0.35);
  }

  private applyCamera(dt: number, roll: number) {
    const c = this.camera;
    c.position.copy(this.camBase);
    if (this.shake > 0) {
      c.position.x += (Math.random() - 0.5) * this.shake; c.position.y += (Math.random() - 0.5) * this.shake;
      this.shake = Math.max(0, this.shake - dt * 1.8);
    }
    c.lookAt(this.camLook);
    if (roll) c.rotateZ(-roll);
  }

  private emitHud(agl: number, warn: string | null, inLift: boolean) {
    const g = this.glider, r = this.run, n = this.thermals.nearest(g.pos);
    let ang: number | null = null;
    if (n && n.d > n.t.r * 0.8) {
      const dx = n.t.x - g.pos.x, dz = n.t.z - g.pos.z;
      ang = Math.atan2(dx * g.right.x + dz * g.right.z, dx * g.hfwd.x + dz * g.hfwd.z);
    }
    this.cb.onHud({
      alt: g.pos.y, agl, vario: this.varioS, speed: g.speed * 3.6, dist: r.dist, score: Math.floor(r.dist) + r.bonus,
      stars: r.stars, rings: r.rings, health: r.health, maxHealth: r.maxHealth, level: r.level, boosts: r.boosts,
      powers: TIMED.filter(k => r.pw[k] > 0).map(k => ({ kind: k, t: r.pw[k], max: POWER_INFO[k].dur })),
      warn, thermalAngle: ang, thermalDist: n ? n.d : 0, inLift, combo: r.combo,
    });
  }

  dispose() {
    cancelAnimationFrame(this.raf);
    this.ro.disconnect(); this.input.dispose(); this.sfx.dispose();
    [this.sky, this.terrain, this.thermals, this.pickups, this.birds, this.fx, this.glider].forEach(o => o.dispose());
    this.renderer.dispose(); this.renderer.domElement.remove();
  }
}

import * as THREE from 'three';
import { clamp } from './noise';
import { lin } from './three-compat';

const G = 9.81;
export const STALL_SPEED = 14;
export interface Controls { pitch: number; roll: number }

/** Modelo del velero: fuselaje esbelto, alas largas con diedro, puntas rojas y cola en T. */
function buildModel() {
  const g = new THREE.Group();
  const white = new THREE.MeshPhongMaterial({ color: lin('#f6f2ea'), shininess: 70, specular: lin('#806050') });
  const red = new THREE.MeshPhongMaterial({ color: lin('#e8462a'), shininess: 50 });
  const glass = new THREE.MeshPhongMaterial({ color: lin('#1a2840'), shininess: 120, specular: lin('#ffd0a0') });
  const add = (geo: THREE.BufferGeometry, mat: THREE.Material, x: number, y: number, z: number, rx = 0, rz = 0) => {
    const m = new THREE.Mesh(geo, mat); m.position.set(x, y, z); m.rotation.set(rx, 0, rz); g.add(m); return m;
  };
  add(new THREE.SphereGeometry(0.55, 16, 10), white, 0, 0, -0.8).scale.set(1, 1, 4.2);
  add(new THREE.CylinderGeometry(0.1, 0.36, 5.2, 8), white, 0, 0.12, 3.4, Math.PI / 2);
  add(new THREE.SphereGeometry(0.42, 12, 8), glass, 0, 0.34, -1.7).scale.set(1, 0.85, 2.3);
  const wing = new THREE.BoxGeometry(7.6, 0.1, 1.0), tip = new THREE.BoxGeometry(1.3, 0.12, 1.02), winglet = new THREE.BoxGeometry(0.08, 0.6, 0.7);
  [1, -1].forEach(s => {
    add(wing, white, 3.8 * s, 0.38, -0.4, 0, 0.06 * s);
    add(tip, red, 7.0 * s, 0.8, -0.4, 0, 0.06 * s);
    add(winglet, red, 7.62 * s, 1.1, -0.35);
  });
  add(new THREE.BoxGeometry(0.1, 1.7, 1.1), white, 0, 0.95, 5.6, -0.25);
  add(new THREE.BoxGeometry(0.12, 0.5, 0.9), red, 0, 1.65, 5.85, -0.25);
  add(new THREE.BoxGeometry(3.4, 0.08, 0.65), white, 0, 1.85, 6.0);
  add(new THREE.BoxGeometry(0.3, 0.06, 2.6), red, 0, 0.52, -0.6);
  const shieldMat = new THREE.MeshBasicMaterial({ color: lin('#6fc8ff'), transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false });
  const shield = add(new THREE.SphereGeometry(8.5, 20, 14), shieldMat, 0, 0.4, 0);
  shield.scale.set(1, 0.45, 1); shield.visible = false;
  const tipL = new THREE.Object3D(), tipR = new THREE.Object3D();
  tipL.position.set(-7.6, 0.85, 0.1); tipR.position.set(7.6, 0.85, 0.1);
  g.add(tipL, tipR);
  return { g, shield, tipL, tipR };
}

/** Física sencilla de planeador: energía (altura <-> velocidad), resistencia, viraje coordinado y pérdida. */
export class Glider {
  readonly group: THREE.Group; readonly shield: THREE.Mesh; readonly tipL: THREE.Object3D; readonly tipR: THREE.Object3D;
  pos = new THREE.Vector3(); vel = new THREE.Vector3();
  fwd = new THREE.Vector3(0, 0, -1); hfwd = new THREE.Vector3(0, 0, -1); right = new THREE.Vector3(1, 0, 0);
  yaw = 0; pitch = -0.08; bank = 0; speed = 26; vy = 0; stall = false; tumble = 0;

  constructor(scene: THREE.Scene) {
    const m = buildModel();
    this.group = m.g; this.shield = m.shield; this.tipL = m.tipL; this.tipR = m.tipR;
    this.group.rotation.order = 'YXZ'; scene.add(this.group);
  }

  reset(x: number, y: number, z: number, yaw: number, speed = 26) {
    this.pos.set(x, y, z);
    Object.assign(this, { yaw, speed, pitch: -0.06, bank: 0, vy: 0, stall: false, tumble: 0 });
    this.group.visible = true; this.sync();
  }

  /** dt en s; lift = velocidad vertical del aire (m/s); tail = viento de cola (m/s). */
  update(dt: number, c: Controls, lift: number, tail: number) {
    this.bank += (c.roll * 0.9 - this.bank) * Math.min(1, dt * 2.6);
    this.yaw -= (G * Math.tan(this.bank)) / Math.max(this.speed, 10) * dt;
    if (Math.abs(c.pitch) > 0.05) this.pitch += c.pitch * 0.75 * dt;
    else this.pitch += (-0.085 - this.pitch) * dt * 0.7;
    this.stall = this.speed < STALL_SPEED;
    if (this.stall) this.pitch -= ((STALL_SPEED - this.speed) * 0.22 + 0.5) * dt;
    this.pitch = clamp(this.pitch, -0.8, 0.5);
    const drag = 0.0016 * this.speed * this.speed + (1 / Math.cos(this.bank) - 1) * 1.1;
    this.speed = clamp(this.speed + (-G * Math.sin(this.pitch) - drag) * dt, 8, 72);
    this.vy = this.speed * Math.sin(this.pitch) + lift;
    this.sync();
    this.vel.copy(this.hfwd).multiplyScalar(this.speed * Math.cos(this.pitch) + tail).y = this.vy;
    this.pos.addScaledVector(this.vel, dt);
    this.group.position.copy(this.pos);
  }

  /** Vuelo automático en círculo (menú). */
  orbit(cx: number, cz: number, r: number, y: number, ang: number) {
    this.pos.set(cx + Math.cos(ang) * r, y + Math.sin(ang * 2) * 3, cz + Math.sin(ang) * r);
    Object.assign(this, { yaw: Math.PI - ang, bank: 0.42, pitch: 0.02, speed: 24 });
    this.sync();
  }

  /** Caída descontrolada tras el choque. */
  crashStep(dt: number, ground: number) {
    this.tumble += dt;
    this.pos.addScaledVector(this.vel, dt * Math.max(0, 1 - this.tumble * 1.5));
    this.pos.y = Math.max(ground + 0.5, this.pos.y - dt * 6);
    this.group.position.copy(this.pos);
    this.group.rotation.z += dt * 2 * Math.max(0, 1 - this.tumble);
  }

  sync() {
    const sy = Math.sin(this.yaw), cy = Math.cos(this.yaw);
    this.hfwd.set(-sy, 0, -cy); this.right.set(cy, 0, -sy);
    this.fwd.copy(this.hfwd).multiplyScalar(Math.cos(this.pitch)).setY(Math.sin(this.pitch));
    this.group.position.copy(this.pos);
    this.group.rotation.set(this.pitch, this.yaw, -this.bank);
  }

  dispose() {
    this.group.traverse(o => { const m = o as THREE.Mesh; m.geometry?.dispose(); (m.material as THREE.Material | undefined)?.dispose(); });
    this.group.parent?.remove(this.group);
  }
}

import type { Controls } from './glider';

/** Teclado (flechas/WASD) + joystick táctil unificados. */
export class Input {
  readonly state: Controls = { pitch: 0, roll: 0 };
  touch = { x: 0, y: 0, active: false };
  invert = false;
  onPause: (() => void) | null = null; onBoost: (() => void) | null = null; onAnyKey: (() => void) | null = null;
  private keys = new Set<string>();

  private down = (e: KeyboardEvent) => {
    const k = e.code;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(k)) e.preventDefault();
    this.onAnyKey?.();
    if (!e.repeat && (k === 'Escape' || k === 'KeyP')) { this.onPause?.(); return; }
    if (!e.repeat && (k === 'Space' || k === 'ShiftLeft' || k === 'ShiftRight')) this.onBoost?.();
    this.keys.add(k);
  };
  private up = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private blur = () => { this.keys.clear(); };

  constructor() {
    window.addEventListener('keydown', this.down); window.addEventListener('keyup', this.up); window.addEventListener('blur', this.blur);
  }

  /** Recalcula los ejes; llamar una vez por fotograma. */
  update() {
    const k = (...c: string[]) => c.some(x => this.keys.has(x));
    let p = (k('ArrowUp', 'KeyW') ? 1 : 0) - (k('ArrowDown', 'KeyS') ? 1 : 0);
    let r = (k('ArrowRight', 'KeyD') ? 1 : 0) - (k('ArrowLeft', 'KeyA') ? 1 : 0);
    if (this.touch.active) { p += this.touch.y; r += this.touch.x; }
    if (this.invert) p = -p;
    this.state.pitch = Math.max(-1, Math.min(1, p));
    this.state.roll = Math.max(-1, Math.min(1, r));
  }

  reset() { this.keys.clear(); this.touch.x = this.touch.y = 0; this.touch.active = false; }

  dispose() {
    window.removeEventListener('keydown', this.down); window.removeEventListener('keyup', this.up); window.removeEventListener('blur', this.blur);
  }
}

/** Ruido de valor 2D determinista + fBm y ruido "ridged" para montañas. */
export function hash2(x: number, z: number, s = 0): number {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(z | 0, 668265263) ^ Math.imul(s | 0, 1442695041);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

/** Ruido de valor suavizado, rango 0..1. */
export function vnoise(x: number, z: number, s = 0): number {
  const ix = Math.floor(x), iz = Math.floor(z), fx = x - ix, fz = z - iz;
  const ux = fx * fx * (3 - 2 * fx), uz = fz * fz * (3 - 2 * fz);
  const a = hash2(ix, iz, s), b = hash2(ix + 1, iz, s), c = hash2(ix, iz + 1, s), d = hash2(ix + 1, iz + 1, s);
  return a + (b - a) * ux + (c - a) * uz + (a - b - c + d) * ux * uz;
}

/** Movimiento browniano fraccional, rango 0..1. */
export function fbm(x: number, z: number, oct = 4, s = 0): number {
  let amp = 0.5, f = 1, sum = 0, norm = 0;
  for (let i = 0; i < oct; i++) { sum += amp * vnoise(x * f, z * f, s + i * 17); norm += amp; amp *= 0.5; f *= 2.03; }
  return sum / norm;
}

/** Ruido de crestas (picos afilados), rango 0..1. */
export function ridged(x: number, z: number, oct = 4, s = 0): number {
  let amp = 0.5, f = 1, sum = 0, norm = 0, w = 1;
  for (let i = 0; i < oct; i++) {
    let n = 1 - Math.abs(vnoise(x * f, z * f, s + i * 31) * 2 - 1);
    n *= n * w; w = Math.min(1, n * 1.6);
    sum += amp * n; norm += amp; amp *= 0.5; f *= 2.1;
  }
  return sum / norm;
}

export const clamp = (v: number, a: number, b: number) => (v < a ? a : v > b ? b : v);
export const sstep = (a: number, b: number, x: number) => { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };
export const rnd = (a: number, b: number) => a + Math.random() * (b - a);

import * as THREE from 'three';
import { POWER_INFO } from './config';
import type { PowerKind } from './config';
import { glowTexture } from './textures';
import { lin } from './three-compat';

interface Item { active: boolean; g: THREE.Object3D; p: THREE.Vector3 }
interface Ring extends Item { mat: THREE.MeshPhongMaterial; disc: THREE.MeshBasicMaterial; yaw: number; done: number }
interface Star extends Item { ph: number }
interface Power extends Item { core: THREE.MeshPhongMaterial; glow: THREE.SpriteMaterial; halo: THREE.Mesh; kind: PowerKind }

const tmp = new THREE.Vector3();
const additive = { blending: THREE.AdditiveBlending, depthWrite: false, transparent: true };
const hide = (o: Item) => { o.active = false; o.g.visible = false; };

function starGeometry(): THREE.ExtrudeGeometry {
  const s = new THREE.Shape();
  for (let i = 0; i < 10; i++) {
    const r = i % 2 ? 0.95 : 2.3, a = (i / 10) * Math.PI * 2 + Math.PI / 2;
    if (i === 0) s.moveTo(Math.cos(a) * r, Math.sin(a) * r); else s.lineTo(Math.cos(a) * r, Math.sin(a) * r);
  }
  return new THREE.ExtrudeGeometry(s, { depth: 0.6, bevelEnabled: false }).center() as THREE.ExtrudeGeometry;
}

/** Anillos dorados, estrellas coleccionables (con halo) y orbes de mejora. */
export class Pickups {
  readonly rings: Ring[] = []; readonly stars: Star[] = []; readonly powers: Power[] = [];
  private scene: THREE.Scene;
  private tex = glowTexture(128);
  private geos: THREE.BufferGeometry[] = [new THREE.TorusGeometry(10, 0.8, 8, 36), new THREE.CircleGeometry(9.3, 32), starGeometry(), new THREE.IcosahedronGeometry(2.3, 1), new THREE.TorusGeometry(4, 0.25, 6, 32)];
  private mats: THREE.Material[] = [];

  constructor(scene: THREE.Scene) {
    this.scene = scene;
    const [torus, disc, sg, ico, halo] = this.geos;
    const m = <T extends THREE.Material>(x: T) => { this.mats.push(x); return x; };
    const group = (...o: THREE.Object3D[]) => { const g = new THREE.Group(); g.add(...o); g.visible = false; scene.add(g); return g; };
    for (let i = 0; i < 12; i++) {
      const mat = m(new THREE.MeshPhongMaterial({ color: lin('#ffd27a'), emissive: lin('#ff8a1c'), shininess: 90, transparent: true }));
      const dm = m(new THREE.MeshBasicMaterial({ color: lin('#ffb050'), opacity: 0.12, side: THREE.DoubleSide, ...additive }));
      this.rings.push({ active: false, g: group(new THREE.Mesh(torus, mat), new THREE.Mesh(disc, dm)), mat, disc: dm, p: new THREE.Vector3(), yaw: 0, done: 0 });
    }
    const smat = m(new THREE.MeshPhongMaterial({ color: lin('#ffe07a'), emissive: lin('#e08a10'), shininess: 100 }));
    const gmat = m(new THREE.SpriteMaterial({ map: this.tex, color: lin('#ffc050'), opacity: 0.8, ...additive }));
    for (let i = 0; i < 40; i++) {
      const glow = new THREE.Sprite(gmat);
      glow.scale.setScalar(11);
      this.stars.push({ active: false, g: group(new THREE.Mesh(sg, smat), glow), p: new THREE.Vector3(), ph: Math.random() * 6 });
    }
    for (let i = 0; i < 3; i++) {
      const core = m(new THREE.MeshPhongMaterial({ color: 0xffffff, emissive: 0xffffff, flatShading: true, shininess: 80 }));
      const glow = m(new THREE.SpriteMaterial({ map: this.tex, ...additive })), h = new THREE.Mesh(halo, core), sp = new THREE.Sprite(glow);
      sp.scale.setScalar(16);
      this.powers.push({ active: false, g: group(new THREE.Mesh(ico, core), h, sp), core, glow, halo: h, kind: 'viento', p: new THREE.Vector3() });
    }
  }

  clear() { [...this.rings, ...this.stars, ...this.powers].forEach(hide); }

  private take<T extends Item>(list: T[], x: number, y: number, z: number): T | null {
    const o = list.find(i => !i.active);
    if (o) { o.active = true; o.p.set(x, y, z); o.g.position.copy(o.p); o.g.visible = true; }
    return o || null;
  }

  spawnRing(x: number, y: number, z: number, yaw: number) {
    const r = this.take(this.rings, x, y, z);
    if (r) { r.done = 0; r.yaw = yaw; r.g.rotation.set(0, yaw, 0); r.g.scale.setScalar(1); r.mat.opacity = 1; r.disc.opacity = 0.12; }
  }

  spawnStar(x: number, y: number, z: number) { this.take(this.stars, x, y, z); }

  spawnPower(x: number, y: number, z: number, kind: PowerKind) {
    const p = this.take(this.powers, x, y, z), c = lin(POWER_INFO[kind].color);
    if (p) { p.kind = kind; p.core.color.copy(c); p.core.emissive.copy(c).multiplyScalar(0.7); p.glow.color.copy(c); }
  }

  /** Anillos atravesados entre prev y pos (cruce del plano dentro del radio). */
  updateRings(dt: number, prev: THREE.Vector3, pos: THREE.Vector3): THREE.Vector3[] {
    const hits: THREE.Vector3[] = [];
    for (const r of this.rings) {
      if (!r.active) continue;
      if (r.done > 0) {
        const k = (r.done += dt) / 0.6;
        r.g.scale.setScalar(1 + k * 0.9); r.mat.opacity = 1 - k; r.disc.opacity = 0.5 * (1 - k);
        if (k >= 1) hide(r);
        continue;
      }
      const nx = -Math.sin(r.yaw), nz = -Math.cos(r.yaw);
      const d0 = (prev.x - r.p.x) * nx + (prev.z - r.p.z) * nz, d1 = (pos.x - r.p.x) * nx + (pos.z - r.p.z) * nz;
      if ((d0 < 0) === (d1 < 0)) continue;
      tmp.copy(pos).sub(r.p);
      if (Math.hypot(tmp.x * Math.cos(r.yaw) - tmp.z * Math.sin(r.yaw), tmp.y) < 10.5) { r.done = 0.001; hits.push(r.p); }
    }
    return hits;
  }

  /** Estrellas: giran, flotan y (con imán) vuelan hacia el jugador. */
  updateStars(dt: number, time: number, pos: THREE.Vector3, magnet: boolean): THREE.Vector3[] {
    const got: THREE.Vector3[] = [];
    for (const s of this.stars) {
      if (!s.active) continue;
      const d = s.p.distanceTo(pos);
      if (magnet && d < 90) s.p.lerp(pos, Math.min(1, dt * 4));
      if (d < 7) { hide(s); got.push(s.p); continue; }
      s.g.position.copy(s.p); s.g.position.y += Math.sin(time * 2 + s.ph) * 0.6;
      s.g.children[0].rotation.y = time * 2.5 + s.ph;
    }
    return got;
  }

  updatePowers(time: number, pos: THREE.Vector3): PowerKind | null {
    let got: PowerKind | null = null;
    for (const p of this.powers) {
      if (!p.active) continue;
      p.g.position.copy(p.p); p.g.position.y += Math.sin(time * 1.6) * 1.2;
      p.g.rotation.y = time * 1.2; p.halo.rotation.x = time * 2;
      if (p.p.distanceTo(pos) < 8.5) { hide(p); got = p.kind; }
    }
    return got;
  }

  despawn(px: number, pz: number) {
    [...this.rings, ...this.stars, ...this.powers].forEach(o => { if (o.active && (o.p.z - pz > 400 || Math.hypot(o.p.x - px, o.p.z - pz) > 1400)) hide(o); });
  }

  dispose() {
    [...this.rings, ...this.stars, ...this.powers].forEach(o => this.scene.remove(o.g));
    this.geos.forEach(g => g.dispose()); this.mats.forEach(m => m.dispose()); this.tex.dispose();
  }
}

import * as THREE from 'three';
import { FOG_FAR, FOG_HEX, FOG_NEAR, SUN_DIR } from './config';
import { groundAt, riverX } from './terrain';
import { cloudTexture, glowTexture, mistTexture } from './textures';
import { LIGHT_K, lin, raw } from './three-compat';
import { rnd } from './noise';

const skyVS = `varying vec3 vDir;
void main(){ vDir = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`;
const skyFS = `uniform vec3 uSun, uHorizon, uMid, uZenith, uGlow, uSunCol;
varying vec3 vDir;
void main(){
  vec3 d = normalize(vDir);
  float h = d.y, sd = max(dot(d, uSun), 0.0);
  vec3 col = mix(uHorizon, uMid, smoothstep(0.0, 0.24, h));
  col = mix(col, uZenith, smoothstep(0.14, 0.85, h));
  col = mix(col, uGlow, pow(sd, 3.0) * (1.0 - smoothstep(-0.05, 0.5, h)) * 0.9);
  col += uSunCol * (pow(sd, 16.0) * 0.32 + pow(sd, 240.0) * 0.9 + smoothstep(0.9990, 0.9995, sd) * 1.4);
  gl_FragColor = vec4(mix(col, uHorizon, smoothstep(0.0, -0.1, h)), 1.0);
}`;

interface Floater { s: THREE.Sprite; drift: number }
const additive = { blending: THREE.AdditiveBlending, depthWrite: false, fog: false, transparent: true };

/** Cielo de atardecer, sol con halo, nubes, bancos de niebla y luces de la escena. */
export class Sky {
  readonly sun = new THREE.Vector3(...SUN_DIR).normalize();
  private scene: THREE.Scene;
  private dome: THREE.Mesh;
  private sunGlow: THREE.Sprite; private sunCore: THREE.Sprite; private clouds: Floater[] = []; private mists: Floater[] = [];
  private textures: THREE.Texture[] = [glowTexture(256), mistTexture(), cloudTexture(1), cloudTexture(2), cloudTexture(3), cloudTexture(4)];
  private mats: THREE.Material[] = []; private objs: THREE.Object3D[] = [];

  constructor(scene: THREE.Scene) {
    this.scene = scene;
    scene.fog = new THREE.Fog(raw(FOG_HEX), FOG_NEAR, FOG_FAR); scene.background = raw(FOG_HEX);
    const u = (h: string) => ({ value: raw(h) });
    const domeMat = new THREE.ShaderMaterial({
      vertexShader: skyVS, fragmentShader: skyFS, side: THREE.BackSide, depthWrite: false, depthTest: false,
      uniforms: { uSun: { value: this.sun }, uHorizon: u(FOG_HEX), uMid: u('#b26f78'), uZenith: u('#2c2856'), uGlow: u('#ffb35e'), uSunCol: u('#fff1cc') },
    });
    this.dome = this.add(new THREE.Mesh(new THREE.SphereGeometry(1900, 32, 16), domeMat));
    this.dome.renderOrder = -10; this.dome.frustumCulled = false;
    const [glow, mist] = this.textures;
    this.sunGlow = this.add(new THREE.Sprite(this.mat(new THREE.SpriteMaterial({ map: glow, color: lin('#ffb060'), opacity: 0.85, ...additive }))));
    this.sunCore = this.add(new THREE.Sprite(this.mat(new THREE.SpriteMaterial({ map: glow, color: lin('#fff2d0'), ...additive }))));
    this.sunGlow.scale.setScalar(900); this.sunCore.scale.setScalar(170); this.sunGlow.renderOrder = this.sunCore.renderOrder = 2;
    for (let i = 0; i < 14; i++) {
      const m = this.mat(new THREE.SpriteMaterial({ map: this.textures[2 + (i % 4)], color: lin(i % 3 ? '#ffc7a8' : '#f7b4b8'), transparent: true, opacity: 0.8, depthWrite: false, fog: false }));
      const s = this.add(new THREE.Sprite(m)), w = rnd(420, 820);
      s.scale.set(w, w * 0.42, 1); this.clouds.push({ s, drift: rnd(2, 6) });
    }
    for (let i = 0; i < 22; i++) {
      const s = this.add(new THREE.Sprite(this.mat(new THREE.SpriteMaterial({ map: mist, color: lin('#ffe2cc'), transparent: true, opacity: rnd(0.25, 0.45), depthWrite: false }))));
      const w = rnd(200, 360);
      s.scale.set(w, w * 0.22, 1); this.mists.push({ s, drift: rnd(1, 3) });
    }
    this.add(new THREE.DirectionalLight(lin('#ffc28e'), 1.55 * LIGHT_K)).position.copy(this.sun).multiplyScalar(1000);
    this.add(new THREE.HemisphereLight(lin('#9a8ad0'), lin('#6a4030'), 0.85 * LIGHT_K));
  }

  private add<T extends THREE.Object3D>(o: T): T { this.scene.add(o); this.objs.push(o); return o; }
  private mat<T extends THREE.Material>(m: T): T { this.mats.push(m); return m; }

  /** Recoloca nubes y niebla alrededor de la cámara (envoltura infinita). */
  place(cam: THREE.Vector3, all = false) {
    this.clouds.forEach(({ s: { position: p } }) => {
      if (!all && Math.hypot(p.x - cam.x, p.z - cam.z) < 1600) return;
      const a = Math.random() * Math.PI * 2, r = all ? rnd(250, 1500) : rnd(1000, 1500);
      p.set(cam.x + Math.cos(a) * r, rnd(480, 760), cam.z + Math.sin(a) * r - (all ? 0 : 300));
    });
    this.mists.forEach(({ s: { position: p } }) => {
      if (!all && Math.hypot(p.x - cam.x, p.z - cam.z) < 950) return;
      const z = cam.z - (all ? rnd(-500, 900) : rnd(500, 900)), x = riverX(z) + rnd(-170, 170);
      p.set(x, groundAt(x, z) + rnd(10, 34), z);
    });
  }

  update(cam: THREE.Vector3, dt: number) {
    this.dome.position.copy(cam);
    this.sunGlow.position.copy(cam).addScaledVector(this.sun, 1500);
    this.sunCore.position.copy(cam).addScaledVector(this.sun, 1480);
    this.clouds.forEach(c => { c.s.position.x += c.drift * dt; });
    this.mists.forEach(m => { m.s.position.x += m.drift * dt; });
    this.place(cam);
  }

  dispose() {
    this.objs.forEach(o => this.scene.remove(o));
    (this.dome.geometry as THREE.BufferGeometry).dispose(); (this.dome.material as THREE.Material).dispose();
    this.mats.forEach(m => m.dispose()); this.textures.forEach(t => t.dispose());
    this.scene.fog = null;
  }
}

import * as THREE from 'three';
import { fbm, hash2, ridged, sstep, vnoise } from './noise';
import { lin, raw } from './three-compat';
import { SUN_DIR, FOG_NEAR, FOG_FAR, FOG_HEX } from './config';

export const CHUNK = 240;
const SEG = 30, RAD = 4, TREES = 22, STEP = CHUNK / SEG;

/** Centro del río (meandros suaves a lo largo de -Z). */
export const riverX = (z: number) => 150 * Math.sin(z * 0.0018) + 60 * Math.sin(z * 0.0049 + 1.3) + 22 * Math.sin(z * 0.012 + 0.4);

/** Altura del terreno: fondo de valle con colinas, cauce del río, laderas y picos con crestas. */
export function heightAt(x: number, z: number): number {
  const d = Math.abs(x - riverX(z)), v = sstep(60, 520, d);
  let h = 5 + fbm(x * 0.006, z * 0.006, 3, 11) * 10 + v * (55 + 330 * ridged(x * 0.0032, z * 0.0032, 4, 5) * v);
  h += (fbm(x * 0.02, z * 0.02, 2, 3) - 0.5) * 10 * v;
  h += sstep(0.55, 0.9, fbm(x * 0.0045 + 40, z * 0.0045, 3, 9)) * 75 * (1 - v) * sstep(45, 100, d);
  return h - (1 - sstep(16, 52, d)) * 15;
}

export const groundAt = (x: number, z: number) => Math.max(heightAt(x, z), 0);

/** Rumbo (yaw) que sigue el valle hacia -Z en la posición z. */
export const valleyYaw = (z: number) => Math.atan2(riverX(z) - riverX(z - 20), 20);

const PAL = { sand: lin('#c7a067'), meadow: lin('#86913f'), gold: lin('#d2a24a'), forest: lin('#45602b'), rock: lin('#7f6358'), rock2: lin('#a8837a'), snow: lin('#f6e4da'), mud: lin('#5c4630') };
const TREE_COLS = [lin('#c0602c'), lin('#d49a36'), lin('#35502a'), lin('#2a4422')];
const C = [0, 0, 0];
const mix = (c: THREE.Color, t: number) => { C[0] += (c.r - C[0]) * t; C[1] += (c.g - C[1]) * t; C[2] += (c.b - C[2]) * t; };
function colorAt(h: number, slope: number, x: number, z: number): number[] {
  const n = vnoise(x * 0.012, z * 0.012, 21), f = fbm(x * 0.006, z * 0.006, 2, 33);
  C[0] = PAL.meadow.r; C[1] = PAL.meadow.g; C[2] = PAL.meadow.b;
  mix(PAL.gold, Math.min(1, sstep(0.3, 0.85, n) * 0.8 + h / 320));
  if (h < 170) mix(PAL.forest, sstep(0.5, 0.6, f) * 0.85);
  mix(n > 0.5 ? PAL.rock2 : PAL.rock, Math.max(sstep(0.6, 1.15, slope), sstep(150, 270, h) * 0.7));
  mix(PAL.snow, sstep(250, 310, h + n * 40) * (1 - sstep(0.95, 1.5, slope)));
  mix(PAL.sand, 1 - sstep(0.5, 5, h));
  if (h < 0) mix(PAL.mud, sstep(0, -4, h));
  return C;
}

const waterVS = `varying vec3 vW;
void main(){ vec4 w = modelMatrix * vec4(position, 1.0); vW = w.xyz; gl_Position = projectionMatrix * viewMatrix * w; }`;
const waterFS = `uniform float uTime; uniform vec3 uSun, uFog, uDeep, uSky, uSunCol; uniform float uNear, uFar;
varying vec3 vW;
void main(){
  vec2 p = vW.xz;
  float wx = sin(p.x*0.09 + uTime*1.3)*0.5 + sin(p.x*0.23 + p.y*0.17 + uTime*2.1)*0.3 + sin(p.y*0.31 - uTime*1.7)*0.2;
  float wz = cos(p.y*0.11 + uTime*1.1)*0.5 + cos(p.x*0.19 - p.y*0.27 + uTime*1.9)*0.3;
  vec3 n = normalize(vec3(wx*0.14, 1.0, wz*0.14)), v = normalize(cameraPosition - vW);
  float fres = pow(1.0 - max(dot(n, v), 0.0), 3.0), sd = max(dot(reflect(-v, n), uSun), 0.0);
  vec3 col = mix(uDeep, uSky, 0.3 + 0.7*fres) + uSunCol*(pow(sd, 140.0)*4.0 + pow(sd, 10.0)*0.35);
  col = mix(pow(max(col, 0.0), vec3(1.0/2.2)), uFog, smoothstep(uNear, uFar, length(cameraPosition - vW)));
  gl_FragColor = vec4(col, 1.0);
}`;

interface Chunk { mesh: THREE.Mesh; geo: THREE.BufferGeometry; key: string; idx: number }

/** Terreno infinito por trozos reciclados, árboles instanciados y agua del río con reflejo del sol. */
export class Terrain {
  readonly group = new THREE.Group();
  private mat = new THREE.MeshPhongMaterial({ vertexColors: true, flatShading: true, shininess: 0, specular: 0x000000 });
  private chunks: Chunk[] = [];
  private byKey = new Map<string, Chunk>();
  private offsets: [number, number][] = [];
  private pending: [number, number][] = [];
  private lcx = 1e9; private lcz = 1e9;
  private treeGeo = new THREE.ConeGeometry(2.6, 10, 6);
  private treeMat = new THREE.MeshPhongMaterial({ flatShading: true, shininess: 0, specular: 0x000000 });
  private trees: THREE.InstancedMesh;
  private waterMat: THREE.ShaderMaterial;
  private water: THREE.Mesh;
  private dummy = new THREE.Object3D();

  constructor(scene: THREE.Scene) {
    for (let dx = -RAD; dx <= RAD; dx++) for (let dz = -RAD; dz <= RAD; dz++) if (dx * dx + dz * dz <= RAD * RAD + 1) this.offsets.push([dx, dz]);
    this.offsets.sort((a, b) => a[0] * a[0] + a[1] * a[1] - b[0] * b[0] - b[1] * b[1]);
    const n = SEG + 1, index: number[] = [];
    for (let i = 0; i < SEG; i++) for (let j = 0; j < SEG; j++) { const a = i * n + j; index.push(a, a + n, a + 1, a + 1, a + n, a + n + 1); }
    this.offsets.forEach((_, idx) => {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(n * n * 3), 3));
      geo.setAttribute('color', new THREE.BufferAttribute(new Float32Array(n * n * 3), 3));
      geo.setIndex(index);
      const mesh = new THREE.Mesh(geo, this.mat);
      mesh.visible = false; this.group.add(mesh);
      this.chunks.push({ mesh, geo, key: '', idx });
    });
    this.treeGeo.translate(0, 5.5, 0);
    this.trees = new THREE.InstancedMesh(this.treeGeo, this.treeMat, this.chunks.length * TREES);
    this.trees.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.trees.frustumCulled = false; this.dummy.scale.setScalar(0); this.dummy.updateMatrix();
    for (let i = 0; i < this.trees.count; i++) { this.trees.setMatrixAt(i, this.dummy.matrix); this.trees.setColorAt(i, TREE_COLS[2]); }
    this.group.add(this.trees);
    this.waterMat = new THREE.ShaderMaterial({
      vertexShader: waterVS, fragmentShader: waterFS,
      uniforms: {
        uTime: { value: 0 }, uSun: { value: new THREE.Vector3(...SUN_DIR).normalize() }, uFog: { value: raw(FOG_HEX) },
        uNear: { value: FOG_NEAR }, uFar: { value: FOG_FAR }, uDeep: { value: lin('#2c3d4a') }, uSky: { value: lin('#e9a98a') }, uSunCol: { value: lin('#ffd9a0') },
      },
    });
    this.water = new THREE.Mesh(new THREE.PlaneGeometry(3400, 3400, 1, 1).rotateX(-Math.PI / 2), this.waterMat);
    this.water.frustumCulled = false; this.group.add(this.water); scene.add(this.group);
  }

  private build(c: Chunk, cx: number, cz: number) {
    const G = SEG + 3, n = SEG + 1, ox = cx * CHUNK, oz = cz * CHUNK, H = new Float32Array(G * G);
    for (let i = 0; i < G; i++) for (let j = 0; j < G; j++) H[i * G + j] = heightAt(ox + (j - 1) * STEP, oz + (i - 1) * STEP);
    const pos = c.geo.getAttribute('position') as THREE.BufferAttribute, col = c.geo.getAttribute('color') as THREE.BufferAttribute;
    const pa = pos.array as Float32Array, ca = col.array as Float32Array;
    for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
      const hi = (i + 1) * G + j + 1, h = H[hi], k = (i * n + j) * 3;
      const sx = (H[hi + 1] - H[hi - 1]) / (2 * STEP), sz = (H[hi + G] - H[hi - G]) / (2 * STEP);
      pa[k] = j * STEP; pa[k + 1] = h; pa[k + 2] = i * STEP;
      const cc = colorAt(h, Math.sqrt(sx * sx + sz * sz), ox + j * STEP, oz + i * STEP);
      ca[k] = cc[0]; ca[k + 1] = cc[1]; ca[k + 2] = cc[2];
    }
    pos.needsUpdate = true; col.needsUpdate = true; c.geo.computeBoundingSphere();
    c.mesh.position.set(ox, 0, oz); c.mesh.visible = true;
    c.key = cx + ',' + cz; this.byKey.set(c.key, c);
    // Árboles: densos en las manchas de bosque, nunca en roca, nieve ni agua.
    for (let t = 0; t < TREES; t++) {
      const x = ox + hash2(cx, cz, t * 2 + 1) * CHUNK, z = oz + hash2(cx, cz, t * 2 + 2) * CHUNK, h = heightAt(x, z);
      const slope = (Math.abs(heightAt(x + 4, z) - h) + Math.abs(heightAt(x, z + 4) - h)) / 4;
      const ok = h > 3 && h < 190 && slope < 0.75 && (fbm(x * 0.006, z * 0.006, 2, 33) > 0.5 || hash2(cx, cz, t + 99) < 0.18);
      const s = ok ? 0.8 + hash2(cx, cz, t + 7) * 1.4 : 0, r = hash2(cz, cx, t + 3);
      this.dummy.position.set(x, h - 0.5, z);
      this.dummy.rotation.set(0, hash2(cx, cz, t) * 6, 0); this.dummy.scale.set(s, s * (0.9 + hash2(t, cz, cx) * 0.6), s); this.dummy.updateMatrix();
      this.trees.setMatrixAt(c.idx * TREES + t, this.dummy.matrix);
      this.trees.setColorAt(c.idx * TREES + t, TREE_COLS[r < 0.12 ? 0 : r < 0.2 ? 1 : r < 0.6 ? 2 : 3]);
    }
    this.trees.instanceMatrix.needsUpdate = true;
    if (this.trees.instanceColor) this.trees.instanceColor.needsUpdate = true;
  }

  /** Mantiene los trozos alrededor de (px,pz); `force` construye todo de golpe. */
  update(px: number, pz: number, camX: number, camZ: number, time: number, force = false) {
    const pcx = Math.floor(px / CHUNK), pcz = Math.floor(pz / CHUNK);
    if (pcx !== this.lcx || pcz !== this.lcz || force) {
      this.lcx = pcx; this.lcz = pcz;
      const need = new Set(this.offsets.map(([dx, dz]) => (pcx + dx) + ',' + (pcz + dz)));
      this.chunks.forEach(c => { if (c.key && !need.has(c.key)) { this.byKey.delete(c.key); c.key = ''; c.mesh.visible = false; } });
      this.pending = this.offsets.map(([dx, dz]) => [pcx + dx, pcz + dz] as [number, number]).filter(([x, z]) => !this.byKey.has(x + ',' + z));
    }
    let budget = force ? 999 : 2;
    while (this.pending.length && budget-- > 0) {
      const [cx, cz] = this.pending.shift() as [number, number], free = this.chunks.find(c => !c.key);
      if (free) this.build(free, cx, cz);
    }
    this.water.position.set(Math.round(camX / 50) * 50, 0, Math.round(camZ / 50) * 50);
    this.waterMat.uniforms.uTime.value = time;
  }

  dispose() {
    this.chunks.forEach(c => c.geo.dispose());
    this.mat.dispose(); this.treeGeo.dispose(); this.treeMat.dispose();
    (this.water.geometry as THREE.BufferGeometry).dispose(); this.waterMat.dispose();
    this.group.parent?.remove(this.group);
  }
}

import * as THREE from 'three';
import { srgbTexture } from './three-compat';

function canvas(w: number, h: number): [HTMLCanvasElement, CanvasRenderingContext2D] {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return [c, c.getContext('2d') as CanvasRenderingContext2D];
}

/** Degradado radial blanco (brillos, sol, partículas). */
export function glowTexture(size = 128, hard = 0): THREE.CanvasTexture {
  const [c, g] = canvas(size, size), r = size / 2;
  const grd = g.createRadialGradient(r, r, 0, r, r, r);
  grd.addColorStop(0, 'rgba(255,255,255,1)');
  grd.addColorStop(Math.max(0.05, hard), 'rgba(255,255,255,0.85)');
  grd.addColorStop(0.4, 'rgba(255,255,255,0.28)');
  grd.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grd; g.fillRect(0, 0, size, size);
  return new THREE.CanvasTexture(c);
}

/** Nube algodonosa: cimas iluminadas por el sol poniente, base rosada. */
export function cloudTexture(seed: number): THREE.CanvasTexture {
  const [c, g] = canvas(256, 128);
  let s = seed * 9301 + 49297;
  const rand = () => { s = (s * 9301 + 49297) % 233280; return s / 233280; };
  for (let i = 0; i < 26; i++) {
    const x = 40 + rand() * 176, y = 50 + rand() * 40 - (Math.abs(x - 128) < 60 ? 14 : 0), r = 16 + rand() * 30;
    const grd = g.createRadialGradient(x, y - r * 0.3, 0, x, y, r);
    grd.addColorStop(0, 'rgba(255,246,236,0.95)'); grd.addColorStop(0.55, 'rgba(236,206,206,0.6)'); grd.addColorStop(1, 'rgba(200,170,190,0)');
    g.fillStyle = grd; g.beginPath(); g.arc(x, y, r, 0, Math.PI * 2); g.fill();
  }
  return srgbTexture(new THREE.CanvasTexture(c)) as THREE.CanvasTexture;
}

/** Banco de niebla alargado y muy suave. */
export function mistTexture(): THREE.CanvasTexture {
  const [c, g] = canvas(256, 64);
  g.scale(4, 1);
  const grd = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  grd.addColorStop(0, 'rgba(255,255,255,0.9)'); grd.addColorStop(0.5, 'rgba(255,255,255,0.4)'); grd.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grd; g.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(c);
}

import * as THREE from 'three';
import { groundAt } from './terrain';
import { glowTexture } from './textures';
import { sstep } from './noise';

const POOL = 12, PER = 70;

export interface Thermal { active: boolean; x: number; z: number; r: number; s: number; base: number; top: number; age: number;
  mesh: THREE.Mesh; mat: THREE.ShaderMaterial; ang: Float32Array; rad: Float32Array; ph: Float32Array }

const VARY = 'varying vec2 vUv; varying vec3 vN; varying vec3 vV; varying float vD;';
const colVS = `${VARY}
void main(){ vUv = uv; vec4 mv = modelViewMatrix * vec4(position, 1.0); vN = normalize(normalMatrix * normal); vV = normalize(-mv.xyz); vD = length(mv.xyz); gl_Position = projectionMatrix * mv; }`;
const colFS = `uniform vec3 uColor; uniform float uOpacity, uTime, uDir;
${VARY}
void main(){
  float edge = pow(1.0 - abs(dot(normalize(vN), normalize(vV))), 2.0);
  float fade = smoothstep(0.0, 0.1, vUv.y) * (1.0 - smoothstep(0.5, 1.0, vUv.y));
  float bands = 0.55 + 0.45 * sin(vUv.y * 40.0 - uTime * 2.6 * uDir + vUv.x * 12.566);
  float vis = smoothstep(30.0, 140.0, vD) * (1.0 - smoothstep(520.0, 1000.0, vD));
  gl_FragColor = vec4(uColor * edge * fade * bands * uOpacity * vis, 1.0);
}`;

const LIFT_COL = new THREE.Color(1.0, 0.66, 0.28), SINK_COL = new THREE.Color(0.3, 0.45, 0.85);

/** Térmicas (columnas doradas de aire ascendente) y descendencias (columnas azuladas). */
export class Thermals {
  readonly list: Thermal[] = [];
  private geo = new THREE.CylinderGeometry(1, 1, 1, 28, 1, true); private pgeo = new THREE.BufferGeometry();
  private tex = glowTexture(64, 0.15);
  private pmat = new THREE.PointsMaterial({ size: 4.5, map: this.tex, vertexColors: true, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, fog: false });
  private points = new THREE.Points(this.pgeo, this.pmat);
  private scene: THREE.Scene;

  constructor(scene: THREE.Scene) {
    this.scene = scene;
    this.geo.translate(0, 0.5, 0);
    for (let i = 0; i < POOL; i++) {
      const mat = new THREE.ShaderMaterial({
        vertexShader: colVS, fragmentShader: colFS, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
        uniforms: { uColor: { value: LIFT_COL.clone() }, uOpacity: { value: 0 }, uTime: { value: 0 }, uDir: { value: 1 } },
      });
      const mesh = new THREE.Mesh(this.geo, mat);
      mesh.visible = false; mesh.frustumCulled = false; scene.add(mesh);
      const ang = new Float32Array(PER), rad = new Float32Array(PER), ph = new Float32Array(PER);
      for (let k = 0; k < PER; k++) { ang[k] = Math.random() * 6.283; rad[k] = Math.sqrt(Math.random()); ph[k] = Math.random(); }
      this.list.push({ active: false, x: 0, z: 0, r: 40, s: 0, base: 0, top: 0, age: 0, mesh, mat, ang, rad, ph });
    }
    this.pgeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(POOL * PER * 3), 3));
    this.pgeo.setAttribute('color', new THREE.BufferAttribute(new Float32Array(POOL * PER * 3), 3));
    this.points.frustumCulled = false; scene.add(this.points);
  }

  clear() { this.list.forEach(t => { t.active = false; t.mesh.visible = false; }); }

  spawn(x: number, z: number, r: number, s: number, top: number): Thermal | null {
    const t = this.list.find(o => !o.active);
    if (!t) return null;
    Object.assign(t, { active: true, x, z, r, s, age: 0, base: groundAt(x, z) - 4 });
    t.top = Math.max(top, t.base + 200);
    t.mesh.visible = true;
    t.mesh.position.set(x, t.base, z);
    t.mesh.scale.set(r * 0.85, t.top - t.base, r * 0.85);
    (t.mat.uniforms.uColor.value as THREE.Color).copy(s > 0 ? LIFT_COL : SINK_COL);
    t.mat.uniforms.uDir.value = s > 0 ? 1 : -1;
    return t;
  }

  /** Velocidad vertical del aire en un punto (m/s), con anillo de descenso alrededor de cada térmica. */
  liftAt(p: THREE.Vector3): number {
    let v = 0;
    for (const t of this.list) {
      if (!t.active) continue;
      const d = Math.hypot(p.x - t.x, p.z - t.z) / t.r;
      if (d > 1.5) continue;
      const k = (1 - sstep(t.top - 90, t.top, p.y)) * Math.min(1, t.age / 1.5);
      if (d < 1) v += t.s * (1 - d * d) * k;
      else if (t.s > 0) v -= 0.8 * (1 - (d - 1) * 2) * k;
    }
    return v;
  }

  nearest(p: THREE.Vector3): { t: Thermal; d: number } | null {
    let best: Thermal | null = null, bd = Infinity;
    for (const t of this.list) {
      if (!t.active || t.s <= 0 || p.y > t.top - 40) continue;
      const d = Math.hypot(p.x - t.x, p.z - t.z);
      if (d < bd) { bd = d; best = t; }
    }
    return best ? { t: best, d: bd } : null;
  }

  update(dt: number, time: number, cam: THREE.Vector3) {
    const pAttr = this.pgeo.getAttribute('position') as THREE.BufferAttribute, cAttr = this.pgeo.getAttribute('color') as THREE.BufferAttribute;
    const pa = pAttr.array as Float32Array, ca = cAttr.array as Float32Array;
    this.list.forEach((t, i) => {
      const o = i * PER * 3;
      if (!t.active) { for (let k = 0; k < PER * 3; k++) { ca[o + k] = 0; } return; }
      t.age += dt;
      const fadeIn = Math.min(1, t.age / 1.5), lift = t.s > 0;
      t.mat.uniforms.uTime.value = time;
      t.mat.uniforms.uOpacity.value = (lift ? 0.2 : 0.16) * fadeIn;
      const H = t.top - t.base, rise = (lift ? 9 : -7) / H, col = lift ? LIFT_COL : SINK_COL;
      for (let k = 0; k < PER; k++) {
        let ph = t.ph[k] + rise * dt;
        ph = ph > 1 ? ph - 1 : ph < 0 ? ph + 1 : ph;
        t.ph[k] = ph;
        t.ang[k] += dt * (0.5 + 0.4 * t.rad[k]) * (lift ? 1 : -1);
        const rr = t.r * t.rad[k] * (0.55 + 0.6 * ph), j = o + k * 3;
        const x = t.x + Math.cos(t.ang[k]) * rr, y = t.base + ph * H, z = t.z + Math.sin(t.ang[k]) * rr;
        pa[j] = x; pa[j + 1] = y; pa[j + 2] = z;
        const dc = Math.hypot(x - cam.x, y - cam.y, z - cam.z);
        const a = Math.sin(ph * Math.PI) * sstep(20, 70, dc) * (1 - sstep(450, 950, dc)) * fadeIn * 0.85;
        ca[j] = col.r * a; ca[j + 1] = col.g * a; ca[j + 2] = col.b * a;
      }
    });
    pAttr.needsUpdate = true; cAttr.needsUpdate = true;
  }

  despawn(px: number, pz: number) {
    this.list.forEach(t => {
      if (t.active && (t.z - pz > 420 || Math.hypot(t.x - px, t.z - pz) > 1400)) { t.active = false; t.mesh.visible = false; }
    });
  }

  dispose() {
    this.list.forEach(t => { this.scene.remove(t.mesh); t.mat.dispose(); });
    this.scene.remove(this.points);
    this.geo.dispose(); this.pgeo.dispose(); this.pmat.dispose(); this.tex.dispose();
  }
}

import * as THREE from 'three';

/** Multiplica TODAS las intensidades de luz (r155+ usa unidades físicas). */
export const LIGHT_K = Number(THREE.REVISION) >= 155 ? Math.PI : 1;

// r170 activa la gestión de color por defecto; r128 no la tiene: la desactivamos para que ambas coincidan.
const CM = (THREE as any).ColorManagement;
if (CM && typeof CM.enabled === 'boolean') CM.enabled = false;

export function setupRenderer(r: THREE.WebGLRenderer) {
  const a = r as any; const T = THREE as any;
  if ('outputColorSpace' in a) a.outputColorSpace = T.SRGBColorSpace; else a.outputEncoding = T.sRGBEncoding;
}

export function srgbTexture(t: THREE.Texture) {
  const a = t as any; const T = THREE as any;
  if ('colorSpace' in a) a.colorSpace = T.SRGBColorSpace; else a.encoding = T.sRGBEncoding;
  return t;
}

const toLin = (c: number) => (c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4));
/** '#hex' pensado en sRGB → lineal (materiales y luces; la salida sRGB lo devuelve tal cual). */
export function lin(hex: string): THREE.Color { const c = new THREE.Color(hex); return c.setRGB(toLin(c.r), toLin(c.g), toLin(c.b)); }
/** '#hex' sin convertir (niebla y shaders que escriben directamente en pantalla). */
export const raw = (hex: string) => new THREE.Color(hex);
